  stations = {
    ["01-1"] = {name="Tal der Prüfungen", tips={{k="交通", text="Kommst du aus einer anderen Startzone, folg in Durotar der Hauptstraße nach Süden, betritt das Tal der Prüfungen von Osten und such Kaltunk."}, {k="取捨", text="Verlorene Waffen, Faule Peons und die beiden Quests im Koven der Burning Blade lassen sich zu zwei Runden zusammenlegen."}, {k="取捨", text="Schließ zuerst die Wichtel-Quest Üble Familiare ab und nimm dann ebenfalls bei Zureetha Medaillon der Burning Blade an.", s={{"Schließ zuerst die Wichtel-Quest Üble Familiare ab und nimm dann ebenfalls bei Zureetha Medaillon der Burning Blade an.", {class={"WARLOCK"}}}}}, {k="提醒", text="Unter Stufe 6? Töte Scheckiger Eber, Skorpidarbeiter oder Übler Familiar auf dem Weg zu Sen'jin.", s={{"Unter Stufe 6?"}, {"Töte Scheckiger Eber, Skorpidarbeiter oder Übler Familiar auf dem Weg zu Sen'jin"}}}}, danger={[1]="An der Biegung im Koven der Burning Blade kannst du mehrere Üble Familiare auf einmal anlocken. Räum vor dem Aufheben der Spitzhacke den Eingang, damit du einen Rückweg hast."}, grind={[1]={mob="Scheckiger Eber", note="Dichte, meist neutrale normale Mobs. Zieh jeweils einen Feind nördlich vom Tal der Prüfungen für Scharfe Zähne auf den Stufen 1-2."}, [2]={mob="Skorpidarbeiter", note="Viele normale, meist neutrale Gegner nordwestlich vom Höhlenbau. Zieh sie einzeln und erledige dabei Stich des Skorpiden."}, [3]={mob="Übler Familiar", note="Viele normale Gegner am Koven der Burning Blade. Am Eingang ziehst du leicht mehrere, kämpfe zuerst am Rand. Farme bis Stufe 6, bevor du das Tal verlässt."}}, supply={[1]={npc="Rarc"}, [2]={npc="Zlagk"}, [3]={npc="Duokna"}}, steps={[1]={npc="Kaltunk", tgt="Kaltunk"}, [2]={npc="Gornek", tgt="Gornek"}, [3]={npc="'Tal der Prüfungen'-Geschenkgutschein", npcObj=true, tag="Optional", desc="Nimm sie nur an, wenn du einen Geschenkgutschein vom Tal der Prüfungen besitzt. Der Geschenkgutschein ist ein Startgegenstand im Rucksack von Charakteren der ursprünglichen Völker. Klicke ihn direkt mit der rechten Maustaste an; auf der Karte gibt es keinen Annahmepunkt."}, [4]={hint="Bringt Magga den 'Tal der Prüfungen'-Geschenkgutschein.", tag="Optional", desc="Nimm die Quest nur an, wenn du den Geschenkgutschein für das Tal der Prüfungen hast."}, [5]={npc="Magga", tgt="Magga", tag="Optional", desc="Nimm die Quest nur an, wenn du den Geschenkgutschein für das Tal der Prüfungen hast."}, [6]={npc="Gornek", tgt="Gornek"}, [7]={npc="Gornek", tgt="Gornek"}, [8]={hint="Tötet 10 scheckige Eber und kehrt dann zu Gornek beim Höhlenbau zurück."}, [9]={npc="Hana'zua", tgt="Hana'zua"}, [10]={hint="Tötet Sarkoth und bringt seine Klaue zu Hana'zua."}, [11]={npc="Hana'zua", tgt="Hana'zua"}, [12]={npc="Hana'zua", tgt="Hana'zua"}, [13]={hint="Sammelt 6 zurückgelassene Übungswaffen und kehrt dann zu Kzan Thornslash im Höhlenbau zurück."}, [14]={npc="Gornek", tgt="Gornek"}, [15]={hint="Informiert Gornek beim Höhlenbau über Hana'zuas Notlage."}, [16]={npc="Kzan Thornslash", tgt="Kzan Thornslash"}, [17]={npc="Gornek", tgt="Gornek"}, [18]={npc="Gornek", tgt="Gornek"}, [19]={npc="Galgar", tgt="Galgar"}, [20]={npc="Großknecht Thazz'ril", tgt="Großknecht Thazz'ril"}, [21]={npc="Zureetha Fargaze", tgt="Zureetha Fargaze"}, [22]={text="Räum erst das Starttal und geh dann zur Höhle im Norden"}, [23]={hint="Bringt 10 Skorpidarbeiterschwänze zu Gornek im Höhlenbau."}, [24]={hint="Bringt Galgar 10 Kaktusäpfel. Ihr erinnert Euch, dass er gesagt hat, man fände sie in der Nähe von Kakteen."}, [25]={hint="Benutzt den Totschläger des Großknechts an faulen Peons, wenn sie schlafen. Weckt 5 Peons auf und bringt dann den Totschläger des Großknechts zu Großknecht Thazz'ril ins Tal der Prüfungen zurück.", desc="Weck fünf schlafende Peons mit der Keule des Vorarbeiters."}, [26]={hint="Tötet 12 üble Familiare.", desc="Als Hexenmeister nimm bei Ruzan stattdessen die Questreihe für den Wichtel an."}, [27]={npc="Gornek", tgt="Gornek"}, [28]={npc="Galgar", tgt="Galgar"}, [29]={npc="Großknecht Thazz'ril", tgt="Großknecht Thazz'ril"}, [30]={npc="Zureetha Fargaze", tgt="Zureetha Fargaze"}, [31]={npc="Großknecht Thazz'ril", tgt="Großknecht Thazz'ril"}, [32]={npc="Ruzan", tgt="Ruzan", desc="Überspring die Wichtelquest im Tal der Prüfungen, wenn du den Wichtel bereits in Deathknell freigeschaltet hast."}, [33]={hint="Bringt 6 Köpfe schändlicher Familiare zu Ruzan.", desc="Überspring die Wichtelquest im Tal der Prüfungen, wenn du den Wichtel bereits in Deathknell freigeschaltet hast."}, [34]={npc="Ruzan", tgt="Ruzan", desc="Überspring die Wichtelquest im Tal der Prüfungen, wenn du den Wichtel bereits in Deathknell freigeschaltet hast."}, [35]={npc="Ruzan", tgt="Ruzan"}, [36]={npc="Zureetha Fargaze", tgt="Zureetha Fargaze"}, [37]={npc="Zureetha Fargaze", tgt="Zureetha Fargaze"}, [38]={hint="Bringt Thazz'rils Hacke zu Großknecht Thazz'ril.", desc="Hol die Spitzhacke im Koven der Burning Blade zusammen mit dem Medaillon der Burning Blade."}, [39]={hint="Bringt Zureetha Fargaze beim Höhlenbau das Medaillon der Burning Blade.", desc="Such Yarrog Schattenbann in der Höhle und plündere 1 Medaillon der Burning Blade."}, [40]={npc="Großknecht Thazz'ril", tgt="Großknecht Thazz'ril"}, [41]={npc="Zureetha Fargaze", tgt="Zureetha Fargaze"}, [42]={npc="Zureetha Fargaze", tgt="Zureetha Fargaze"}, [43]={npc="Verschollenes Tagebuch", npcObj=true, desc="Das verlorene Tagebuch liegt bei Zureetha Fargaze."}, [44]={npc="Gornek", tgt="Gornek", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [45]={hint="Lest das einfache Pergament und sprecht mit Frang im Tal der Prüfungen.", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [46]={npc="Frang", tgt="Frang", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [47]={npc="Gornek", tgt="Gornek", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [48]={hint="Lest die einfache Schrifttafel und sprecht mit Frang im Tal der Prüfungen.", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [49]={npc="Frang", tgt="Frang", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [50]={npc="Gornek", tgt="Gornek", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [51]={hint="Lest das verschlüsselte Pergament und sprecht mit Rwag im Tal der Prüfungen.", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [52]={npc="Rwag", tgt="Rwag", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [53]={npc="Gornek", tgt="Gornek", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [54]={hint="Lest die verschlüsselte Schrifttafel und sprecht mit Rwag im Tal der Prüfungen.", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [55]={npc="Rwag", tgt="Rwag", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [56]={npc="Gornek", tgt="Gornek", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [57]={hint="Lest das mit Runen beschriebene Pergament und sprecht mit Shikrik im Tal der Prüfungen.", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [58]={npc="Shikrik", tgt="Shikrik", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [59]={npc="Gornek", tgt="Gornek", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [60]={hint="Sprecht mit Shikrik im Tal der Prüfungen.", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [61]={npc="Shikrik", tgt="Shikrik", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [62]={npc="Canaga Earthcaller", tgt="Canaga Earthcaller"}, [63]={hint="Bringt 2 Teufelspirscherhufe zu Canaga Earthcaller im Tal der Prüfungen."}, [64]={npc="Canaga Earthcaller", tgt="Canaga Earthcaller"}, [65]={npc="Canaga Earthcaller", tgt="Canaga Earthcaller", desc="Trink Sapta, um die Schwache Erdmanifestation sehen zu können."}, [66]={hint="Sucht den Geisterfelsen und trinkt das Erdsapta.", desc="Trink Sapta, um die Schwache Erdmanifestation sehen zu können."}, [67]={npc="Schwache Erdmanifestation", tgt="Schwache Erdmanifestation", desc="Trink Sapta, um die Schwache Erdmanifestation sehen zu können."}, [68]={npc="Schwache Erdmanifestation", tgt="Schwache Erdmanifestation", desc="Schließe die Quest ab, um dein Erdtotem zu erhalten."}, [69]={hint="Bringt den Rohquarz zu Canaga Earthcaller im Tal der Prüfungen.", desc="Schließe die Quest ab, um dein Erdtotem zu erhalten."}, [70]={npc="Canaga Earthcaller", tgt="Canaga Earthcaller", desc="Schließe die Quest ab, um dein Erdtotem zu erhalten."}, [71]={npc="Gornek", tgt="Gornek"}, [72]={hint="Lest das geätzte Pergament und sprecht mit Jen'shan im Tal der Prüfungen."}, [73]={npc="Jen'shan", tgt="Jen'shan"}, [74]={npc="Gornek", tgt="Gornek"}, [75]={npc="Jen'shan", tgt="Jen'shan"}, [76]={npc="Gornek", tgt="Gornek"}, [77]={hint="Lest das besudelte Pergament und sprecht mit Nartok im Höhlenbau im Tal der Prüfungen."}, [78]={npc="Nartok", tgt="Nartok"}, [79]={npc="Gornek", tgt="Gornek"}, [80]={hint="Lest die besudelte Tafel und sprecht mit Nartok im Höhlenbau im Tal der Prüfungen."}, [81]={npc="Nartok", tgt="Nartok"}, [82]={npc="Gornek", tgt="Gornek", desc="Gib zuerst Scharfe Zähne ab; erst dann bekommst du die Steintafel."}, [83]={hint="Lest die geheiligte Schrifttafel und sprecht mit Ken'jai außerhalb des Höhlenbaus im Tal der Prüfungen.", desc="Gib zuerst Scharfe Zähne ab; erst dann bekommst du die Steintafel."}, [84]={npc="Ken'jai", tgt="Ken'jai", desc="Gib zuerst Scharfe Zähne ab; erst dann bekommst du die Steintafel."}, [85]={npc="Ken'jai", tgt="Ken'jai"