    ["01-2"] = {name="Durotar", nameA="Durotar: {a:367} & {a:362}", shortA="Durotar: {a:367} +", tips={{k="取捨", text="Mach die Quest Neuer Rucksack. Sammle die Segeltuchreste zusammen mit den anderen Zielen in der Burg Tiragarde."}, {k="取捨", text="Gib zuerst Vernichtet die Verräter ab, um Aus den Wrackteilen geborgen... freizuschalten. Mach Aus den Wrackteilen geborgen... und Ein geistvolles Getränk auf derselben Runde."}, {k="取捨", text="Heb die Dungeonquestreihe in der Kluft der Schatten für später auf. Nimm die Questreihe Verborgene Feinde bei Thrall erst an, wenn du in den Ragefireabgrund willst. Das Offiziersabzeichen für den ersten Abschnitt bekommst du im nördlichen Lager der Burning Blade."}, {k="提醒", text="Unter Stufe 12? Mach Sicherung der Linien, Die Knochenhöhle oder die ersten paar Bedrohung von unten-Quests.", s={{"Unter Stufe 12?"}, {"Mach Sicherung der Linien, Die Knochenhöhle oder die ersten paar Bedrohung von unten-Quests"}}}}, danger={[1]="Die Treppen und Türen in Burg Tiragarde können Matrosen von oben ziehen. Räum zuerst die Außenwand und den Eingang frei.", [2]="Meeresriesen durchstreifen das Naga-Gebiet an der Nordküste. Räum nahe Mobs, bevor du einen ziehst. Zieh dich am Ufer zurück, wenn es brenzlig wird."}, grind={[1]={mob="Marinesoldat von Kul Tiras", note="Dichte normale Mobs bei Burg Tiragarde. In den Fluren ziehst du leicht mehrere, kämpfe zuerst draußen. Sammle nebenbei Segeltuchreste für den neuen Rucksack."}, [2]={mob="Schlachtwache der Grimmhauer", note="Normale Mobs sammeln sich westlich von Klingenhügel. Zieh sie am Lagerrand einzeln heran und achte auf Patrouillen. Passt gut zu Übergriff."}, [3]={mob="Sturmhexe der Staubschwingen", note="Normale Mobs, auch Zauberwirker, tummeln sich im nördlichen Durotar. Zieh sie hinter Deckung einzeln heran. Mach Sicherung der Linien oder farme vor Orgrimmar auf Stufe 12."}}, supply={[1]={npc="Trayexir"}, [2]={npc="Gastwirt Grosk"}, [3]={npc="Wuark"}, [4]={npc="Gastwirt Grosk"}, [5]={npc="Ghrawt"}, [6]={npc="Doras"}}, steps={[1]={npc="Ukor", tgt="Ukor", desc="Such Ukor auf dem Weg vom Tal der Prüfungen nach Sen'jin."}, [2]={npc="Meister Gadrin", tgt="Meister Gadrin"}, [3]={npc="Meister Gadrin", tgt="Meister Gadrin"}, [4]={npc="Meister Gadrin", tgt="Meister Gadrin"}, [5]={npc="Meister Gadrin", tgt="Meister Gadrin"}, [6]={npc="Lar Prowltusk", tgt="Lar Prowltusk"}, [7]={npc="Vel'rin Fang", tgt="Vel'rin Fang"}, [8]={npc="Vel'rin Fang", tgt="Vel'rin Fang"}, [9]={npc="Xar'Ti", tgt="Xar'Ti"}, [10]={npc="Meister Vornal", tgt="Meister Vornal"}, [11]={npc="Meister Vornal", tgt="Meister Vornal"}, [12]={npc="Pa'zula", tgt="Pa'zula", tag="Optional", desc="Mach die Quest nur, wenn du die Materialien durch Entzaubern beschaffen kannst."}, [13]={text="Melde dich zuerst in Klingenhügel"}, [14]={hint="Tötet 6 Kammschattenkrabbler und 6 Kammschattenlauerer im Süden von Durotar und berichtet anschließend Gar'tok in Klingenhügel davon."}, [15]={npc="Brakk", tgt="Brakk"}, [16]={npc="Brakk", tgt="Brakk"}, [17]={hint="Setzt Euch an Brakks einfaches Lagerfeuer und wartet, bis Ihr den verbesserten Ruhebonus erhalten habt."}, [18]={npc="Brakk", tgt="Brakk"}, [19]={npc="Brakk", tgt="Brakk", tag="Optional"}, [20]={npc="Brakk", tgt="Brakk", text="Grundlagen des Zeltens (beliebiger Beruf)", tag="Optional"}, [21]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [22]={npc="Gar'Thok", tgt="Gar'Thok"}, [23]={npc="Gastwirt Grosk", tgt="Gastwirt Grosk"}, [24]={text="Bind in Klingenhügel zuerst deinen Ruhestein bei Gastwirt Grosk (51.51, 41.64).", bindA="{a:362}"}, [25]={npc="Tai'jin", tgt="Tai'jin", desc="Trainiere zuerst Geringes Heilen (Rang 2) und Machtwort: Seelenstärke."}, [26]={hint="Findet die Grunzerin Kor'ja und heilt ihre Wunden mit Hilfe von 'Geringes Heilen' (Rang 2). Belegt sie danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Tai'jin in Klingenhügel zurück.", desc="Trainiere zuerst Geringes Heilen (Rang 2) und Machtwort: Seelenstärke."}, [27]={npc="Tai'jin", tgt="Tai'jin", desc="Trainiere zuerst Geringes Heilen (Rang 2) und Machtwort: Seelenstärke."}, [28]={npc="Gar'Thok", tgt="Gar'Thok"}, [29]={npc="Gar'Thok", tgt="Gar'Thok"}, [30]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [31]={npc="Furl Scornbrow", tgt="Furl Scornbrow", star={"Handgefertigte Ledertasche"}}, [32]={npc="Turroc", tgt="Turroc"}, [33]={npc="Koch Torka", tgt="Koch Torka"}, [34]={npc="Koch Torka", tgt="Koch Torka"}, [35]={hint="Sprecht mit Koch Torka in Klingenhügel, um das Kochen zu erlernen.", tag="Optional"}, [36]={npc="Koch Torka", tgt="Koch Torka", tag="Optional"}, [37]={npc="Dwukk", tgt="Dwukk", tag="Optional"}, [38]={npc="Mukdrak", tgt="Mukdrak", tag="Optional"}, [39]={npc="Rawrk", tgt="Rawrk", tag="Optional"}, [40]={npc="Krunn", tgt="Krunn", tag="Optional"}, [41]={text="Burg Tiragarde → die Wracks → Kolkarklippe und Die Echoinseln"}, [42]={hint="Tötet 10 Matrosen von Kul Tiras, 8 Marinesoldaten von Kul Tiras sowie Lieutenant Benedict und kehrt dann zu Gar'Thok in Klingenhügel zurück."}, [43]={hint="Furl Scornbrow im Wachturm von Klingenhügel möchte 8 Segeltuchreste haben."}, [44]={hint="Sammelt die Räuberstreitaxt, den Räuberbogen und den Räuberschild um Burg Tiragarde und bringt sie anschließend zu Turroc in Klingenhügel zurück."}, [45]={npc="Vergilbter Umschlag", npcObj=true, desc="Besiege Lieutenant Benedict und nimm den Schlüssel. Öffne oben die Truhe, um den Vergilbten Umschlag zu erhalten."}, [46]={npc="Ukors verlorener Beutel", npcObj=true, tag="Optional", desc="Starte die Quest nur, wenn du den Rucksack unterwegs findest. Geh südwärts zu Ukor."}, [47]={text="Kehr von Burg Tiragarde zu Klingenhügel zurück. Herd, falls fertig."}, [48]={npc="Gar'Thok", tgt="Gar'Thok"}, [49]={npc="Gar'Thok", tgt="Gar'Thok"}, [50]={npc="Gar'Thok", tgt="Gar'Thok"}, [51]={npc="Gar'Thok", tgt="Gar'Thok", tag="Optional"}, [52]={npc="Turroc", tgt="Turroc", desc="Du kannst dieselbe Quest beim Grunzer von Klingenhügel annehmen (53.06, 42.48)."}, [53]={npc="Furl Scornbrow", tgt="Furl Scornbrow", star={"Handgefertigte Ledertasche"}}, [54]={hint="Gar'Thok von Klingenhügel möchte, dass Ihr 3 Gnomen-Werkzeuge aus den Wrackteilen vor der Küste holt."}, [55]={hint="Bringt Meister Vornal in Sen'jin 4 intakte Makruraaugen und 8 Phiolen Kriechersekret."}, [56]={hint="Bringt den Beutel zu Ukor im Süden von Durotar.", tag="Optional"}, [57]={npc="Ukor", tgt="Ukor", tag="Optional"}, [58]={hint="Lar Prowltusk außerhalb von Sen'jin möchte, dass Ihr die 3 Sets der Angriffspläne zerstört, die innerhalb der Kolkarklippe verwahrt werden."}, [59]={npc="Pal'juh", tgt="Pal'juh", desc="Pal'juh befindet sich an der Kolkarklippe. Räum die Straße frei, bevor du mit der Eskorte beginnst."}, [60]={hint="Helft Pal'juh, aus der Kolkarklippe zu entkommen, und berichtet anschließend Meister Vornal in Sen'jin davon.", desc="Pal'juh befindet sich an der Kolkarklippe. Räum die Straße frei, bevor du mit der Eskorte beginnst."}, [61]={npc="Meister Vornal", tgt="Meister Vornal"}, [62]={npc="Meister Vornal", tgt="Meister Vornal", desc="Pal'juh befindet sich an der Kolkarklippe. Räum die Straße frei, bevor du mit der Eskorte beginnst."}, [63]={npc="Lar Prowltusk", tgt="Lar Prowltusk"}, [64]={hint="Bringt dem Koch Torka in Klingenhügel 3 Schwanzpeitscher-Eier."}, [65]={hint="Bringt Vel'rin Fang in Sen'jin 4 Durotar-Tigerfelle."}, [66]={hint="Holt Minshinas Schädel aus dem Kreis der Macht auf den Echoinseln."}, [67]={hint="Besiegt Zalazane."}, [68]={hint="Sammelt 8 vergessene Loagötzen auf den Echoinseln. Bringt sie Meister Gadrin in Sen'jin."}, [69]={hint="Bringt die Eier der Blutkrallenmatriarchin zu Xar'Ti in Sen'jin."}, [70]={hint="Pa'zula in Sen'jin möchte, dass Ihr 3 leuchtende Rückstände sammelt. Leuchtende Rückstände können durch das Entzaubern von verhexten Anhängern gefunden werden, die Trolle auf den Echoinseln fallen lassen.", tag="Optional", desc="Hier droppt unter anderem der Anhänger Verhexung. Leuchtende Rückstände erhältst du durch Entzaubern."}, [71]={npc="Vel'rin Fang", tgt="Vel'rin Fang"}, [72]={npc="Meister Gadrin", tgt="Meister Gadrin"}, [73]={npc="Meister Gadrin", tgt="Meister Gadrin"}, [74]={npc="Meister Gadrin", tgt="Meister Gadrin"}, [75]={npc="Xar'Ti", tgt="Xar'Ti"}, [76]={npc="Pa'zula", tgt="Pa'zula", tag="Optional"}, [77]={npc="Lau'Tiki", tgt="Lau'Tiki", tag="Optional"}, [78]={text="Kehr mit dem Ruhestein nach Klingenhügel zurück oder nimm die Nordstraße."}, [79]={npc="Koch Torka", tgt="Koch Torka"}, [80]={npc="Gar'Thok", tgt="Gar'Thok"}, [81]={text="Westlich von Klingenhügel und nördlich von Durotar"}, [82]={hint="Tötet für Gar'Thok in Klingenhügel 4 Stacheleber der Grimmhauer, 4 Späher der Grimmhauer, 4 Staubläufer der Grimmhauer und 4 Schlachtwachen der Grimmhauer."}, [83]={hint="Koch Torka in Klingenhügel möchte, dass Ihr 8 Kaktusfeigen im Revier der Grimmhauer westlich der Stadt sammelt."}, [84]={npc="Gar'Thok", tgt="Gar'Thok"}, [85]={npc="Koch Torka", tgt="Koch Torka"}, [86]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar", desc="Min. Stufe 9."}, [87]={hint="Findet Heglan Shadeeye nördlich von Burg Tiragarde.", desc="Min. Stufe 9."}, [88]={npc="Heglan Shadeeye", tgt="Heglan Shadeeye", desc="Min. Stufe 9."}, [89]={npc="Heglan Shadeeye", tgt="Heglan Shadeeye"}, [90]={hint="Findet Hinweise darauf, was Heglan Shadeeye angegriffen hat."}, [91]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [92]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [93]={hint="Bringt Fizzles Klaue zu Orgnil Soulscar in Klingenhügel."}, [94]={hint="Sammelt 9 Nagastachelflossen ein."}, [95]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [96]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [97]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [98]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar", tag="Gruppe empfohlen, Optional", desc="Elite-Meeresriese an der Nordküste. Gruppen bilden oder bei Bedarf überspringen."}, [99]={hint="Tötet den Meeresriesen an der Nordküste von Durotar und bringt einen Beweis für Euren Erfolg zurück.", tag="Gruppe empfohlen, Optional", desc="Elite-Meeresriese an der Nordküste. Gruppen bilden oder bei Bedarf überspringen."}, [100]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar", tag="Gruppe empfohlen, Optional", desc="Elite-Meeresriese an der Nordküste. Gruppen bilden oder bei Bedarf überspringen."}, [101]={npc="Margoz", tgt="Margoz"}, [102]={npc="Margoz", tgt="Margoz"}, [103]={hint="Besorgt von den Kultisten an der Knochenhöhle ein paar Senghalsbänder."}, [104]={npc="Margoz", tgt="Margoz"}, [105]={npc="Margoz", tgt="Margoz", tag="Optional, Wenn du vorbeikommst"}, [106]={text="Optionale EP-Quests vor Stufe 12"}, [107]={npc="Rezlak", tgt="Rezlak"}, [108]={hint="Holt 5 Säcke Vorräte und bringt sie Rezlak in der Nähe von Orgrimmar."}, [109]={npc="Rezlak", tgt="Rezlak"}, [110]={npc="Rezlak", tgt="Rezlak"}, [111]={hint="Tötet für Rezlak in der Nähe der Staubwindklamm 12 Wilde der Staubschwingen und 8 Sturmhexen der Staubschwingen."}, [112]={npc="Rezlak", tgt="Rezlak"}, [113]={npc="Misha Tor'kren", tgt="Misha Tor'kren"}, [114]={hint="Bringt Misha Tor'kren auf dem Bauernhof nordwestlich von Klingenhügel einen Hinweis auf Krons Schicksal."}, [115]={npc="Misha Tor'kren", tgt="Misha Tor'kren"}, [116]={npc="Matte Sturmkugel", npcObj=true, tag="Optional", desc="Nimm die Quest nur an, wenn du die Matte Sturmkugel aufhebst."}, [117]={hint="Bringt die matte Sturmkugel zu Rezlak in der Nähe der Staubwindklamm.", tag="Optional", desc="Nimm die Quest nur an, wenn du die Matte Sturmkugel aufhebst."}, [118]={npc="Rezlak", tgt="Rezlak", tag="Optional", desc="Nimm die Quest nur an, wenn du die Matte Sturmkugel aufhebst."}, [119]={npc="Rezlak", tgt="Rezlak", tag="Optional"}, [120]={hint="Bringt 5 geladene Donnerechsenorgane zu Rezlak in der Nähe der Staubwindklamm.", tag="Optional"}, [121]={npc="Rezlak", tgt="Rezlak", tag="Optional"}, [122]={npc="Halikors Huf", npcObj=true, tag="Optional", desc="Wenn du Halikor findest und besiegen kannst, plündere seinen Huf."}, [123]={text="Abholungen in Orgrimmar und Übergabe in Crossroads"}, [124]={npc="Kaplak", tgt="Kaplak", desc="Einführungsquest für Orcs. Trolle können Die Shattered-Hand direkt bei Therzok annehmen."}, [125]={hint="Sprecht mit Therzok in der Kluft der Schatten in Orgrimmar.", desc="Einführungsquest für Orcs. Trolle können Die Shattered-Hand direkt bei Therzok annehmen."}, [126]={npc="Therzok", tgt="Therzok", desc="Einführungsquest für Orcs. Trolle können Die Shattered-Hand direkt bei Therzok annehmen."}, [127]={npc="Sian'dur", tgt="Sian'dur", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Thotar."}, [128]={hint="Sprecht mit Thotar in Klingenhügel.", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Thotar."}, [129]={npc="Thotar", tgt="Thotar", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Thotar."}, [130]={npc="Kali Remik", tgt="Kali Remik", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Thotar."}, [131]={hint="Sprecht mit Thotar in Klingenhügel.", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Thotar."}, [132]={npc="Thotar", tgt="Thotar", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Thotar."}, [133]={npc="Kary Thunderhorn", tgt="Kary Thunderhorn", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Thotar."}, [134]={hint="Sprecht mit Thotar in Klingenhügel.", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Thotar."}, [135]={npc="Thotar", tgt="Thotar", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Thotar."}, [136]={npc="Thotar", tgt="Thotar"}, [137]={hint="Benutzt die Zähmrute, um einen scheckigen Terroreber zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Thotar in Klingenhügel."}, [138]={npc="Thotar", tgt="Thotar"}, [139]={npc="Thotar", tgt="Thotar", desc="Voraussetzung: Die Zähmung der Bestie. Das zweite Ziel ist ein Brandungskriecher."}, [140]={hint="Benutzt die Zähmrute, um einen Brandungskriecher zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Thotar in Klingenhügel.", desc="Voraussetzung: Die Zähmung der Bestie. Das zweite Ziel ist ein Brandungskriecher."}, [141]={npc="Thotar", tgt="Thotar", desc="Voraussetzung: Die Zähmung der Bestie. Das zweite Ziel ist ein Brandungskriecher."}, [142]={npc="Thotar", tgt="Thotar", desc="Voraussetzung: Die Zähmung der Bestie. Zähme als Drittes einen Gepanzerten Skorpid."}, [143]={hint="Benutzt die Zähmrute, um einen gepanzerten Skorpid zu zähmen. Übt Eure Fertigkeiten und kehrt zu Thotar in Klingenhügel zurück.", desc="Voraussetzung: Die Zähmung der Bestie. Zähme als Drittes einen Gepanzerten Skorpid."}, [144]={npc="Thotar", tgt="Thotar", desc="Voraussetzung: Die Zähmung der Bestie. Zähme als Drittes einen Gepanzerten Skorpid."}, [145]={npc="Thotar", tgt="Thotar", desc="Trainier nach dem Zähmen die Haustierfähigkeiten im Tal der Ehre in Orgrimmar."}, [146]={hint="Sprecht mit Ormak Grimshot in Orgrimmar.", desc="Trainier nach dem Zähmen die Haustierfähigkeiten im Tal der Ehre in Orgrimmar."}, [147]={npc="Ormak Grimshot", tgt="Ormak Grimshot", desc="Trainier nach dem Zähmen die Haustierfähigkeiten im Tal der Ehre in Orgrimmar."}, [148]={npc="Ophek", tgt="Ophek", tag="Optional", desc="Du kannst die Einstiegsquest überspringen. Horde-Hexenmeister können diese Quest annehmen."}, [149]={hint="Sprecht mit Gan'rul Bloodeye in Orgrimmar.", tag="Optional", desc="Du kannst die Einstiegsquest überspringen. Horde-Hexenmeister können diese Quest annehmen."}, [150]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", tag="Optional", desc="Du kannst die Einstiegsquest überspringen. Horde-Hexenmeister können diese Quest annehmen."}, [151]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", desc="Hol die Steintafel in der Knochenhöhle östlich von Orgrimmar."}, [152]={hint="Holt die Schrifttafel der Verga für Gan'rul Bloodeye in Orgrimmar.", desc="Hol die Steintafel in der Knochenhöhle östlich von Orgrimmar."}, [153]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", desc="Hol die Steintafel in der Knochenhöhle östlich von Orgrimmar."}, [154]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", desc="Benutze am Beschwörungskreis bei Neeru die Inschrift, besiege den Leerwandler und gib die Quest dann bei Gan'rul ab."}, [155]={hint="Beschwört mit Hilfe der Glyphen der Beschwörung einen Leerwandler, unterwerft ihn und bringt dann die Glyphen der Beschwörung zu Gan'rul Bloodeye in Orgrimmar zurück.", desc="Benutze am Beschwörungskreis bei Neeru die Inschrift, besiege den Leerwandler und gib die Quest dann bei Gan'rul ab."}, [156]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", desc="Benutze am Beschwörungskreis bei Neeru die Inschrift, besiege den Leerwandler und gib die Quest dann bei Gan'rul ab."}, [157]={npc="Tai'jin", tgt="Tai'jin"}, [158]={hint="Sprecht mit Ur'kyo in Orgrimmar."}, [159]={npc="Ur'kyo", tgt="Ur'kyo"}, [160]={npc="Ur'kyo", tgt="Ur'kyo"}, [161]={text="Hast du Orgrimmar-Quests, folg der Hauptstraße nach Norden und betritt die Stadt durch das Südtor. Schalte den Flugpunkt bei Doras frei (45.12, 63.89). Gib in der Nähe gleich die nächsten Stadtquests ab."}, [162]={npc="Nazgrel", tgt="Nazgrel", tag="Optional"}, [163]={hint="Bringt Neeru Fireblade in Orgrimmar ein Senghalsband-Muster.", tag="Optional"}, [164]={npc="Neeru Fireblade", tgt="Neeru Fireblade", tag="Optional"}, [165]={npc="Neeru Fireblade", tgt="Neeru Fireblade", desc="Erst nach der Abgabe des Beispielhalsbands erhältlich; gib sie am Farwatch-Posten im Brachland ab."}, [166]={npc="Thuwd", tgt="Thuwd", tag="Optional"}, [167]={npc="Snang", tgt="Snang", tag="Optional"}, [168]={npc="Whuut", tgt="Whuut", tag="Optional"}, [169]={npc="Jhag", tgt="Jhag", tag="Optional"}, [170]={npc="Jandi", tgt="Jandi", tag="Optional"}, [171]={npc="Karolek", tgt="Karolek", tag="Optional"}, [172]={hint="Bringt Halikors Huf nach Orgrimmar.", tag="Optional"}, [173]={npc="Kamari", tgt="Kamari", tag="Optional"}, [174]={npc="Therzok", tgt="Therzok", desc="Stiehl zuerst Tazans Schlüssel und hol dir dann seine Tasche. Behalte den Schlüssel, du brauchst ihn im nächsten Abschnitt."}, [175]={npc="Uthel'nay", tgt="Uthel'nay", tag="Optional", desc="Nimm die Quest in Orgrimmar bei Uthel'nay oder in Thunder Bluff bei Thurston Xane (25.18, 20.96) an. In Sen'jin kannst du Jujuhaufen direkt bei Un'Thuwa annehmen."}, [176]={text="Gib erst die Stadtquests ab, dann nutz den Ruhestein nach Klingenhügel. Hat er Abklingzeit, folg der Hauptstraße in Durotar nach Süden. Bist du nicht in die Stadt gegangen, mach gleich mit dem nächsten Schritt weiter."}, [177]={npc="Swart", tgt="Swart", desc="Beginn in Klingenhügel. Die Folgequests von Kranal teilen sich mit der Einführung im Dorf der Bluthufe, siehe Crossroads. Eine Kette genügt."}, [178]={hint="Sprecht mit Un'thuwa.", tag="Optional", desc="Bist du in Sen'jin, nimm Jujuhaufen direkt bei Un'Thuwa an."}, [179]={npc="Un'Thuwa", tgt="Un'Thuwa", tag="Optional", desc="Bist du in Sen'jin, nimm Jujuhaufen direkt bei Un'Thuwa an."}, [180]={npc="Un'Thuwa", tgt="Un'Thuwa"}, [181]={hint="Zerstört 4 Jujuhaufen und kehrt dann zu Un'thuwa in Sen'jin zurück."}, [182]={npc="Un'Thuwa", tgt="Un'Thuwa"}, [184]={npc="Takrin Pathseeker", tgt="Takrin Pathseeker", desc="Mindestens Stufe 10. Warte bis etwa Stufe 12, bevor du nach Crossroads gehst."}, [185]={hint="Folgt der westlichen Straße aus Klingenhügel ins Brachland und über die Brücke."}, [186]={npc="Ak'Zeloth", tgt="Ak'Zeloth"}, [187]={npc="Kargal Battlescar", tgt="Kargal Battlescar"}, [188]={npc="Kargal Battlescar", tgt="Kargal Battlescar"}, [189]={hint="Sucht Kranal Fiss im Brachland.", desc="Beginn in Klingenhügel. Die Folgequests von Kranal teilen sich mit der Einführung im Dorf der Bluthufe, siehe Crossroads. Eine Kette genügt."}, [190]={npc="Kranal Fiss", tgt="Kranal Fiss", desc="Beginn in Klingenhügel. Die Folgequests von Kranal teilen sich mit der Einführung im Dorf der Bluthufe, siehe Crossroads. Eine Kette genügt."}, [191]={text="Geh vom Farwatch-Posten nach Westen. Bieg an der T-Kreuzung nach Süden ab und erreiche Crossroads im Brachland."}, [192]={hint="Folgt der Straße von Kargals fernem Farwatch-Außenposten nach Westen."}, [193]={npc="Sergra Darkthorn", tgt="Sergra Darkthorn"}, [194]={nodeA="{a:380}", node="The Crossroads", desc="Schalte den Flugpunkt bei Devrak frei. Du kannst nebenbei deinen Ruhestein bei Gastwirt Boorand Plainswind binden."}, [195]={text="Folge von Crossroads der Hauptstraße nach Osten bis Ratchet und schalte dabei gleich den Flugpunkt von Ratchet frei."}, [196]={hint="Tötet Tazan und bringt seinen Ranzen zu Therzok in der Kluft der Schatten in Orgrimmar.", desc="Stiehl zuerst Tazans Schlüssel und hol dir dann seine Tasche. Behalte den Schlüssel, du brauchst ihn im nächsten Abschnitt."}, [197]={text="Flieg von Ratchet nach Orgrimmar und geh zurück in die Kluft der Schatten zu Therzok."}, [198]={npc="Therzok", tgt="Therzok", desc="Stiehl zuerst Tazans Schlüssel und hol dir dann seine Tasche. Behalte den Schlüssel, du brauchst ihn im nächsten Abschnitt."}, [199]={npc="Therzok", tgt="Therzok", desc="Behalte den Schlüssel und öffne die Tasche erst, wenn Therzok dir Die Shattered-Hand gibt.", star={"Klinge der Geschicklichkeit", {"ROGUE"}}}, [200]={hint="Stehlt Tazans Schlüssel, öffnet seinen Ranzen damit und bringt den Inhalt zu Therzok in der Kluft der Schatten in Orgrimmar.", desc="Behalte den Schlüssel und öffne die Tasche erst, wenn Therzok dir Die Shattered-Hand gibt."}, [201]={npc="Therzok", tgt="Therzok", desc="Behalte den Schlüssel und öffne die Tasche erst, wenn Therzok dir Die Shattered-Hand gibt.", star={"Klinge der Geschicklichkeit", {"ROGUE"}}}}},
    ["01-3"] = {name="Camp Narache", tips={{k="交通", text="Kommst du aus einer anderen Startzone, geh zuerst zum Dorf der Bluthufe und folg dann der Straße nach Süden über Red Cloud Mesa bis Camp Narache."}, {k="取捨", text="Führ Ritus der Kraft, Tötet Spitzhauer! und Die Kampfeber in einer Dornrankenklamm-Schleife aus. Akzeptiere Angriff auf Camp Narache, wenn du die Karte plünderst."}, {k="提醒", text="Unter Stufe 6? Töte Kampfeber oder Stacheleber der Borstennacken am Rand von Dornrankenklamm und gehe dann zu Dorf der Bluthufe.", s={{"Unter Stufe 6?"}, {"Töte Kampfeber oder Stacheleber der Borstennacken am Rand von Dornrankenklamm und gehe dann zu Dorf der Bluthufe"}}}}, danger={[1]="Die Stachelebern drängen sich an der schmalen Rampe in Dornrankenklamm. Räum die Rampe, bevor du Häuptling Spitzhauer Dornenmantel ziehst. Zieh dich bei Bedarf zur Red Cloud Mesa zurück."}, grind={[1]={mob="Ebenenschreiter", note="Dichte, meist neutrale normale Mobs am südöstlichen Brunnen von Camp Narache. Zieh während Die Jagd beginnt jeweils einen Feind heraus."}, [2]={mob="Bergpuma", note="Dichte, meist neutrale normale Mobs am Südhang von Red Cloud Mesa. Zieh einen Feind nach dem anderen, um die in Die Jagd geht weiter benötigten Felle zu erhalten."}, [3]={mob="Kampfeber der Borstennacken", note="Normale Mobs gruppieren sich unter den Stachelebern der Borstennacken in Dornrankenklamm. Räum zuerst den Rand. Kombiniere es mit Kampfeber und Ritus der Kraft."}}, supply={[1]={npc="Bronk Steelrage"}, [2]={npc="Moodan Sungrain"}, [3]={npc="Kawnie Softbreeze"}}, steps={[1]={npc="Camp Narache-Geschenkgutschein", npcObj=true, tag="Optional", desc="Nimm sie nur an, wenn du einen Geschenkgutschein von Camp Narache besitzt. Der Geschenkgutschein ist ein Startgegenstand im Rucksack von Charakteren der ursprünglichen Völker. Klicke ihn direkt mit der rechten Maustaste an; auf der Karte gibt es keinen Annahmepunkt."}, [2]={hint="Bringt Vorn Skyseer den 'Camp Narache'-Geschenkgutschein.", tag="Optional", desc="Nimm die Quest nur an, wenn du den Geschenkgutschein für Camp Narache hast."}, [3]={npc="Vorn Skyseer", tgt="Vorn Skyseer", tag="Optional", desc="Nimm die Quest nur an, wenn du den Geschenkgutschein für Camp Narache hast."}, [4]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [5]={npc="Häuptling Hawkwind", tgt="Häuptling Hawkwind"}, [6]={hint="Grull Hawkwind im Camp Narache möchte, dass Ihr ihm 7 Ebenenschreiterfedern und 7 Stücke Ebenenschreiterfleisch bringt."}, [7]={hint="Häuptling Hawkwind möchte, dass Ihr seine Mutter beim Brunnen südöstlich vom Camp Narache sucht."}, [8]={npc="Großmutter Hawkwind", tgt="Großmutter Hawkwind"}, [9]={npc="Großmutter Hawkwind", tgt="Großmutter Hawkwind"}, [10]={hint="Holt eine Wasserkanne vom Wasserbrunnen.", desc="Hol die Wasserkanne aus dem Brunnen neben Großmutter Hawkwind."}, [11]={npc="Häuptling Hawkwind", tgt="Häuptling Hawkwind"}, [12]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [13]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [14]={npc="Grull Hawkwind", tgt="Grull Hawkwind", desc="Schließe Die Jagd beginnt ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [15]={hint="Lest die einfache Nachricht und sprecht mit Harutt Thunderhorn im Camp Narache.", desc="Schließe Die Jagd beginnt ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [16]={npc="Harutt Thunderhorn", tgt="Harutt Thunderhorn", desc="Schließe Die Jagd beginnt ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [17]={npc="Grull Hawkwind", tgt="Grull Hawkwind", desc="Schließe Die Jagd beginnt ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [18]={hint="Lest die mit Runen beschriftete Nachricht und sprecht mit Meela Dawnstrider im Camp Narache.", desc="Schließe Die Jagd beginnt ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [19]={npc="Meela Dawnstrider", tgt="Meela Dawnstrider", desc="Schließe Die Jagd beginnt ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [20]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [21]={hint="Lest die geätzte Nachricht und sprecht mit Lanka Farshot in Red Cloud Mesa."}, [22]={npc="Lanka Farshot", tgt="Lanka Farshot"}, [23]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [24]={hint="Lest die tiefgrüne Notiz und sprecht mit Gart Mistrunner im Camp Narache."}, [25]={npc="Gart Mistrunner", tgt="Gart Mistrunner"}, [26]={npc="Häuptling Hawkwind", tgt="Häuptling Hawkwind"}, [27]={npc="Kriegerheldin Windfeather", tgt="Kriegerheldin Windfeather"}, [28]={hint="Grull Hawkwind im Camp Narache möchte, dass Ihr ihm 10 Bergpumapelze bringt."}, [29]={hint="Begebt Euch zu Seher Graytongue, der in den Hügeln direkt südlich des Lagers Narache lebt."}, [30]={npc="Seher Graytongue", tgt="Seher Graytongue"}, [31]={npc="Seher Graytongue", tgt="Seher Graytongue"}, [32]={npc="Seher Graytongue", tgt="Seher Graytongue", desc="Bring den Weihrauch innerhalb von 10 Minuten nach Erhalt zum Südostaltar.", star={"Versengter Lederbeutel"}}, [33]={hint="Bringt das glimmende Räucherwerk innerhalb von zehn Minuten zum Schrein von An'she und Mu'sha in den südöstlichen Hügeln, bevor es zu Asche verbrennt.", desc="Bring den Weihrauch innerhalb von 10 Minuten nach Erhalt zum Südostaltar."}, [34]={npc="Ritualfeuer", npcObj=true, desc="Bring den Weihrauch innerhalb von 10 Minuten nach Erhalt zum Südostaltar.", star={"Versengter Lederbeutel"}}, [35]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [36]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [37]={hint="Tötet die Borstennacken in der Dornrankenklamm und bringt Häuptling Hawkwind im Camp Narache 12 Gürtel der Borstennacken."}, [38]={hint="Bringt den Kopf von Häuptling Spitzhauer Dornenmantel zu Kriegerheld Windfeather nach Red Cloud Mesa."}, [39]={hint="Grull Hawkwind im Camp Narache möchte, dass Ihr für ihn Kampfeber tötet und ihm 8 Kampfeberschnauzen und 8 Kampfeberflanken bringt."}, [40]={npc="Schmutzbefleckte Karte", npcObj=true, tag="Optional", desc="Plündere die schmutzige Karte von Stacheleber der Borstennacken und klicke mit der rechten Maustaste darauf."}, [41]={npc="Häuptling Hawkwind", tgt="Häuptling Hawkwind"}, [42]={npc="Kriegerheldin Windfeather", tgt="Kriegerheldin Windfeather"}, [43]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [44]={npc="Häuptling Hawkwind", tgt="Häuptling Hawkwind", tag="Optional"}, [45]={npc="Häuptling Hawkwind", tgt="Häuptling Hawkwind"}, [46]={npc="Häuptling Hawkwind", tgt="Häuptling Hawkwind"}, [47]={npc="Antur Fallow", tgt="Antur Fallow", desc="Nimm die Quest bei Antur Fallow erst an, wenn du westlich am Lager vorbeikommst."}, [48]={npc="Seherin Ravenfeather", tgt="Seherin Ravenfeather"}, [49]={hint="Bringt 2 Dosen Ritualsalbe zu der Seherin Ravenfeather im Camp Narache."}, [50]={npc="Seherin Ravenfeather", tgt="Seherin Ravenfeather"}, [51]={npc="Seherin Ravenfeather", tgt="Seherin Ravenfeather", desc="Trink Sapta, um die Schwache Erdmanifestation sehen zu können."}, [52]={hint="Sucht den Kodofels und trinkt das Erdsapta.", desc="Trink Sapta, um die Schwache Erdmanifestation sehen zu können."}, [53]={npc="Schwache Erdmanifestation", tgt="Schwache Erdmanifestation", desc="Trink Sapta, um die Schwache Erdmanifestation sehen zu können."}, [54]={npc="Schwache Erdmanifestation", tgt="Schwache Erdmanifestation", desc="Schließe die Quest ab, um dein Erdtotem zu erhalten."}, [55]={hint="Bringt den Rohquarz zu der Seherin Ravenfeather im Camp Narache.", desc="Schließe die Quest ab, um dein Erdtotem zu erhalten."}, [56]={npc="Seherin Ravenfeather", tgt="Seherin Ravenfeather", desc="Schließe die Quest ab, um dein Erdtotem zu erhalten."}, [57]={text="Verlass Red Cloud Mesa und folge der Straße nach Norden bis zum Dorf der Bluthufe."}}},
    ["01-4"] = {name="Mulgore", nameA="Mulgore: {a:222}", tips={{k="取捨", text="Mach Ritus der Sicht (drei Teile), Ritus der Weisheit und Reise nach Thunder Bluff am Stück. Am letzten Ziel schaltest du den Flugpunkt frei."}, {k="取捨", text="Gib jede Brunnenquest ab, bevor du die nächste annimmst (nur Tauren). Überspring ab Stufe 12 die Nebenquests zu den Wildmane-Brunnen (nur Tauren).", s={{"Gib jede Brunnenquest ab, bevor du die nächste annimmst (nur Tauren). Überspring ab Stufe 12 die Nebenquests zu den Wildmane-Brunnen (nur Tauren).", {race={"Tauren"}}}}}, {k="取捨", text="In Thunder Bluff kannst du die Vorquests für den Ragefireabgrund annehmen. Die Kraft des Feindes wird auf die Probe gestellt und Die Suche nach dem verloren gegangenen Ranzen holst du bei Rahauro erst, wenn du ins Verlies gehst."}, {k="提醒", text="Fehlen dir kurz vor Stufe 12 noch EP, farm Harpyien im Norden von Mulgore, an den Roten Steinen oder in der Mine der Venture Company.", s={{"Fehlen dir kurz vor Stufe 12 noch EP, farm Harpyien im Norden von Mulgore, an den Roten Steinen oder in der Mine der Venture Company"}}}}, danger={[1]="Die Mine der Venture Company zieht Patrouillen und Bergleute gleich mit in den Kampf. Räum zuerst den Rand, nimm das Klemmbrett und verlass den Tunnel."}, grind={[1]={mob="Präriepirscher", note="Verstreute normale Mobs nördlich vom Dorf der Bluthufe. Zieh sie einzeln ins Gras und achte auf Streuner. Sammle nebenbei die Materialien für Mazzranache."}, [2]={mob="Vorsteher der Venture Co.", note="Normale Mobs sammeln sich um die Mine der Venture Company. Zieh von außen an und achte auf Arbeiter und Patrouillen. Kombiniere es mit den Minenquests."}, [3]={mob="Matriarchin der Windfurien", note="Dichte normale Mobs im Harpyienlager im Nordwesten von Mulgore, darunter Zauberwirker. Zieh am Rand entlang, um nicht das ganze Lager zu ziehen. Farme hier, wenn du dich Stufe 12 näherst."}}, supply={[1]={npc="Gastwirt Kauth"}, [2]={npc="Harant Ironbrace"}, [3]={npc="Gastwirt Kauth"}, [4]={npc="Kennah Hawkseye"}, [5]={npc="Tal"}}, steps={[1]={hint="Bringt das Vorratsbündel zu Kaga Wildhoof in der Nähe des Dorfs der Bloodhoof."}, [2]={npc="Kaga Wildhoof", tgt="Kaga Wildhoof"}, [3]={npc="Kaga Wildhoof", tgt="Kaga Wildhoof"}, [4]={hint="Setzt Euch an Kagas einfaches Lagerfeuer und wartet, bis Ihr den verbesserten Ruhebonus erhalten habt."}, [5]={npc="Kaga Wildhoof", tgt="Kaga Wildhoof"}, [6]={npc="Kaga Wildhoof", tgt="Kaga Wildhoof", tag="Optional"}, [7]={npc="Kaga Wildhoof", tgt="Kaga Wildhoof", text="Grundlagen des Zeltens (beliebiger Beruf)", tag="Optional"}, [8]={hint="Bringt Baine Bloodhoof in Bloodhoof Hawkwinds Totem. Folgt der Straße, die aus dem Camp Narache herausführt."}, [9]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [10]={npc="Gastwirt Kauth", tgt="Gastwirt Kauth"}, [11]={text="Bind deinen Ruhestein zuerst bei Gastwirt Kauth im Dorf der Bluthufe (45.93, 64.16).", bindA="{a:222}"}, [12]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [13]={npc="Zarlman Two-Moons", tgt="Zarlman Two-Moons"}, [14]={npc="Zarlman Two-Moons", tgt="Zarlman Two-Moons"}, [15]={npc="Harken Windtotem", tgt="Harken Windtotem"}, [16]={npc="Maur Raincaller", tgt="Maur Raincaller"}, [17]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [18]={npc="Kriegerheld Wildrunner", tgt="Kriegerheld Wildrunner"}, [19]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [20]={npc="Krang Stonehoof", tgt="Krang Stonehoof"}, [21]={hint="Besiegt 3 andere Spielercharaktere in Duellen oder Novizenkrieger für Tang Stonehoof."}, [22]={npc="Krang Stonehoof", tgt="Krang Stonehoof"}, [23]={npc="Ahab Wheathoof", tgt="Ahab Wheathoof"}, [24]={hint="Sprecht mit Pyall Silentstride im Dorf der Bloodhoof, um das Kochen zu erlernen.", tag="Optional"}, [25]={npc="Pyall Silentstride", tgt="Pyall Silentstride", tag="Optional"}, [26]={npc="Yonn Deepcut", tgt="Yonn Deepcut", tag="Optional"}, [27]={npc="Vira Younghoof", tgt="Vira Younghoof", tag="Optional"}, [28]={npc="Uthan Stillwater", tgt="Uthan Stillwater", tag="Optional"}, [29]={npc="Chaw Stronghide", tgt="Chaw Stronghide", tag="Optional"}, [30]={text="Östlich von Dorf der Bluthufe → Karawane und Zentauren"}, [31]={hint="Sammelt 2 Quellsteine und 2 Bernsteinkörner und bringt sie Zarlman Two-Moons in Bloodhoof."}, [32]={hint="Bringt Harken Windtotem in Bloodhoof 8 Trophäen-Sturzfliegerkiele."}, [33]={hint="Bringt Maur Raincaller in Bloodhoof ein Herz eines Präriewolfs, einen Knochen eines Flachlandpumas, eine Schuppe eines Ebenenschreiters und einen Muskelmagen eines Sturzfliegers."}, [34]={hint="Bringt Mull Thunderhorn in Bloodhoof 6 Präriewolftatzen und 4 Ebenenschreiterkrallen."}, [35]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [36]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [37]={hint="Benutzt das Säuberungstotem von Winterhoof beim Wasserbrunnen von Winterhoof und kehrt dann zu Mull Thunderhorn zurück."}, [38]={hint="Findet Langläuferin Malah Longwind östlich des Dorfes der Bloodhoof, nahe Mulgore."}, [39]={npc="Malah Longwind", tgt="Malah Longwind"}, [40]={npc="Malah Longwind", tgt="Malah Longwind"}, [41]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker"}, [42]={hint="Morin Cloudstalker möchte, dass Ihr den Inhalt einer Nachschubkiste der überfallenen Karawane untersucht."}, [43]={npc="Versiegelte Vorratskiste", npcObj=true}, [44]={npc="Versiegelte Vorratskiste", npcObj=true}, [45]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker"}, [46]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker"}, [47]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker"}, [48]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [49]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [50]={hint="Bringt den Bericht von Langläuferin Malah zu Kriegerheld Wildrunner im Dorf der Bloodhoof."}, [51]={npc="Kriegerheld Wildrunner", tgt="Kriegerheld Wildrunner"}, [52]={npc="Kriegerheld Wildrunner", tgt="Kriegerheld Wildrunner"}, [53]={hint="Bringt den Bericht von Langläuferin Malah zu Baine Bloodhoof."}, [54]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [55]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [56]={npc="Harken Windtotem", tgt="Harken Windtotem"}, [57]={npc="Zarlman Two-Moons", tgt="Zarlman Two-Moons"}, [58]={npc="Zarlman Two-Moons", tgt="Zarlman Two-Moons"}, [59]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [60]={npc="Ruul Eagletalon", tgt="Ruul Eagletalon"}, [61]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane"}, [62]={text="Westen: Palemane und die Ausgrabungsstätte. Folge der Vision zum Seher"}, [63]={hint="Tötet 10 Gerber der Bleichmähnen, 8 Kürschner der Bleichmähnen und 5 Wilderer der Bleichmähnen und kehrt dann zu Baine Bloodhoof in Bloodhoof zurück."}, [64]={hint="Sammelt 5 Ausgrabungsleiterhacken ein."}, [65]={hint="Bringt Ruul Eagletalon in Bloodhoof 8 Windfurienkrallen."}, [66]={hint="Trinkt vor dem Stammesfeuer in Bloodhoof das Wasser der Seher und folgt der Vision, sobald sie erscheint.", desc="Trink das Wasser der Seher neben dem Stammesfeuer und folge der Vision nach Nordwesten. Erledige unterwegs offene Quests."}, [67]={npc="Perith Stormhoof", tgt="Perith Stormhoof", tag="Optional", desc="Willst du nicht extra früh nach Thunder Bluff, nimm die Quest jetzt an und mach die Eskorte. Gib sie beim ersten Besuch in Thunder Bluff ab."}, [68]={hint="Helft Perith Stormhoof bei der Flucht aus dem Bleichmähnenfels und meldet Cairne Bloodhoof in Thunder Bluff, dass er in Sicherheit ist.", tag="Optional"}, [69]={npc="Seher Wiserunner", tgt="Seher Wiserunner"}, [70]={npc="Seher Wiserunner", tgt="Seher Wiserunner"}, [71]={hint="Bringt Mull Thunderhorn 6 Pirscherklauen und 6 Pumaklauen."}, [72]={text="Kehr mit dem Ruhestein zum Dorf der Bluthufe zurück und gib die Quests im Westen gemeinsam ab."}, [73]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [74]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [75]={npc="Ruul Eagletalon", tgt="Ruul Eagletalon"}, [76]={npc="Maur Raincaller", tgt="Maur Raincaller"}, [77]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [78]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [79]={hint="Ahab Weizhuf in Bloodhoof in Mulgore möchte, dass Ihr seinen geliebten Hund Kyle den Wilden füttert.", desc="Bring ein Zartes Schreiterfleisch mit und warte, bis Kyle nah genug kommt, bevor du ihn fütterst."}, [80]={npc="Ahab Wheathoof", tgt="Ahab Wheathoof"}, [81]={text="Nördliche Brunnen, rote Steine und die Mine im Nordosten"}, [82]={hint="Benutzt dasSäuberungstotem von Thunderhorn beim Wasserbrunnen von Thunderhorn und kehrt dann zu Mull zurück."}, [83]={hint="Reist von Thunder Bluff gen Osten zu den Teufelsfelsen und sprecht mit dem Vorfahrengeist."}, [84]={npc="Hüter des Wissens Raintotem", tgt="Hüter des Wissens Raintotem"}, [85]={hint="Der Hüter des Wissens Raintotem möchte, dass Ihr bei den Teufelsfelsen 8 Eindringlinge der Borstennacken tötet."}, [86]={npc="Vorfahrengeist", tgt="Vorfahrengeist"}, [87]={npc="Vorfahrengeist", tgt="Vorfahrengeist"}, [88]={npc="Hüter des Wissens Raintotem", tgt="Hüter des Wissens Raintotem"}, [89]={hint="Tötet 6 Zentauren der Galak und 4 Kundschafter der Galak und bringt den Kopf von Herak dem Plünderer zu Baine Bloodhoof."}, [90]={hint="Tötet für Morin Cloudstalker in der Nähe von Bloodhoof 14 Tagelöhner der Venture Co. und 6 Vorsteher der Venture Co."}, [91]={hint="Tötet Vorsteher Fizsprocket und bringt Morin Cloudstalker in der Nähe von Bloodhoof dessen Klemmbrett."}, [92]={npc="Twizwick Sprocketgrind", tgt="Twizwick Sprocketgrind", tag="Optional"}, [93]={npc="Expansionspläne für Mulgore", npcObj=true, tag="Optional", desc="Plündere Expansionspläne für Mulgore von Vorsteher Fizsprocket, um die Quest zu starten."}, [94]={hint="Sammelt die übrigen Seiten von Vorsteher Fizsprockets Notizbuch in der Mine der Venture Co. und bringt sie zu Morin Cloudstalker am Dorf der Bloodhoof.", tag="Optional", desc="Sammle alle drei Notizen in der Mine der Venture Company ein, bevor du gehst."}, [95]={hint="Besiegt Chakuyak und bringt ihr Fell mit."}, [96]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker"}, [97]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker"}, [98]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker", tag="Optional"}, [99]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker", tag="Gruppe empfohlen, Optional", desc="Unter Stufe 12? Erledige weitere Quests in der Nähe der Mine."}, [100]={hint="Bringt den Mechanoroderschlüssel zu Morin Cloudstalker am Dorf der Bloodhoof.", tag="Gruppe empfohlen, Optional", desc="Unter Stufe 12? Erledige weitere Quests in der Nähe der Mine."}, [101]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker", tag="Gruppe empfohlen, Optional", desc="Unter Stufe 12? Erledige weitere Quests in der Nähe der Mine."}, [102]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane"}, [103]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [104]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [105]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [106]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [107]={hint="Bringt Mull Thunderhorn in Bloodhoof 8 Präriealphazähne."}, [108]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [109]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn", tag="Optional"}, [110]={hint="Benutzt das Säuberungstotem von Wildmane beim Wasserbrunnen von Wildmane und kehrt dann zu Mull Thunderhorn zurück.", tag="Optional"}, [111]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn", tag="Optional"}, [112]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn", tag="Optional"}, [113]={npc="Skorn Whitecloud", tgt="Skorn Whitecloud"}, [114]={hint="Bringt Melor Stonehoof in Thunder Bluff 4 Flachlandstreunerklauen."}, [115]={text="Flugpunkt in Thunder Bluff freischalten, dann nach Crossroads"}, [116]={npc="Narm Skychaser", tgt="Narm Skychaser", desc="Beginn im Dorf der Bluthufe. Ruf des Feuers setzt du in Crossroads mit der Schamanenklassenquest fort. Du kannst sie auch direkt bei Kranal annehmen."}, [117]={npc="Kary Thunderhorn", tgt="Kary Thunderhorn", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Yaw Sharpmane."}, [118]={hint="Sprecht mit Yaw Sharpmane in Bloodhoof.", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Yaw Sharpmane."}, [119]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Yaw Sharpmane."}, [120]={npc="Sian'dur", tgt="Sian'dur", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Yaw Sharpmane."}, [121]={hint="Sprecht mit Yaw Sharpmane in Bloodhoof.", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Yaw Sharpmane."}, [122]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Yaw Sharpmane."}, [123]={npc="Thotar", tgt="Thotar", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Yaw Sharpmane."}, [124]={hint="Sprecht mit Yaw Sharpmane in Bloodhoof.", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Yaw Sharpmane."}, [125]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Yaw Sharpmane."}, [126]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane"}, [127]={hint="Benutzt die Zähmrute, um einen ausgewachsenen Ebenenschreiter zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Sharpmane in Bloodhoof."}, [128]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane"}, [129]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane"}, [130]={hint="Benutzt die Zähmrute, um einen Präriepirscher zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Sharpmane in Bloodhoof."}, [131]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane"}, [132]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane"}, [133]={hint="Benutzt die Zähmrute, um einen Sturzflieger zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Sharpmane in Bloodhoof."}, [134]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane"}, [135]={npc="Yaw Sharpmane", tgt="Yaw Sharpmane", desc="Trainier nach allen drei Zähmungen die Haustierfähigkeiten auf der Anhöhe der Jäger in Thunder Bluff."}, [136]={hint="Sprecht mit Holt Thunderhorn auf der Anhöhe der Jäger in Thunder Bluff.", desc="Trainier nach allen drei Zähmungen die Haustierfähigkeiten auf der Anhöhe der Jäger in Thunder Bluff."}, [137]={npc="Holt Thunderhorn", tgt="Holt Thunderhorn", desc="Trainier nach allen drei Zähmungen die Haustierfähigkeiten auf der Anhöhe der Jäger in Thunder Bluff."}, [138]={npc="Gennia Runetotem", tgt="Gennia Runetotem", tag="Optional", desc="Mach eine der drei Einleitungen oder nimm Moonglade direkt bei Turak Runetotem an."}, [139]={hint="Sprecht mit Turak Runetotem auf der Anhöhe der Ältesten in Thunder Bluff.", tag="Optional", desc="Mach eine der drei Einleitungen oder nimm Moonglade direkt bei Turak Runetotem an."}, [140]={npc="Turak Runetotem", tgt="Turak Runetotem", tag="Optional", desc="Mach eine der drei Einleitungen oder nimm Moonglade direkt bei Turak Runetotem an."}, [141]={npc="Gastwirtin Pala", tgt="Gastwirtin Pala", tag="Optional", desc="Mach eine der drei Einleitungen oder nimm Moonglade direkt bei Turak Runetotem an."}, [142]={hint="Sprecht mit Turak Runetotem auf der Anhöhe der Ältesten in Thunder Bluff.", tag="Optional", desc="Mach eine der drei Einleitungen oder nimm Moonglade direkt bei Turak Runetotem an."}, [143]={npc="Turak Runetotem", tgt="Turak Runetotem", tag="Optional", desc="Mach eine der drei Einleitungen oder nimm Moonglade direkt bei Turak Runetotem an."}, [144]={npc="Gastwirtin Gryshka", tgt="Gastwirtin Gryshka", tag="Optional", desc="Mach eine der drei Einleitungen oder nimm Moonglade direkt bei Turak Runetotem an."}, [145]={hint="Sprecht mit Turak Runetotem auf der Anhöhe der Ältesten in Thunder Bluff.", tag="Optional", desc="Mach eine der drei Einleitungen oder nimm Moonglade direkt bei Turak Runetotem an."}, [146]={npc="Turak Runetotem", tgt="Turak Runetotem", tag="Optional", desc="Mach eine der drei Einleitungen oder nimm Moonglade direkt bei Turak Runetotem an."}, [147]={npc="Turak Runetotem", tgt="Turak Runetotem", desc="Lern den Teleport bei Turak Runetotem und reise damit direkt nach Moonglade."}, [148]={hint="Benutzt den Zauber 'Teleportation: Moonglade', um nach Moonglade zu reisen. Wenn Ihr dort ankommt, sprecht mit Dendrite Starblaze in Nighthaven.", desc="Lern den Teleport bei Turak Runetotem und reise damit direkt nach Moonglade."}, [149]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Lern den Teleport bei Turak Runetotem und reise damit direkt nach Moonglade."}, [150]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Sprich mit Großer Bärengeist im Nordwesten und kehr danach nach Nighthaven zurück."}, [151]={hint="Sucht den großen Bärengeist im nordwestlichen Moonglade auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Starblaze nach Nighthaven in Moonglade zurück.", desc="Sprich mit Großer Bärengeist im Nordwesten und kehr danach nach Nighthaven zurück."}, [152]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Sprich mit Großer Bärengeist im Nordwesten und kehr danach nach Nighthaven zurück."}, [153]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [154]={text="Such in Nighthaven Bunthen Plainswind (nur Druiden; 44.28, 45.87) auf und flieg nach Thunder Bluff. Wenn dein Ruhestein sinnvoll gebunden und nicht auf Abklingzeit ist, kannst du stattdessen auch zurückkehren. Nimm nicht den normalen Flugpunkt bei Faustron südlich von Moonglade; diese Route ist noch nicht freigeschaltet."}, [155]={hint="Kehrt nach Thunder Bluff zurück und sprecht mit Turak Runetotem auf der Anhöhe der Ältesten."}, [156]={npc="Turak Runetotem", tgt="Turak Runetotem"}, [157]={npc="Turak Runetotem", tgt="Turak Runetotem"}, [158]={text="Folge der mittleren Straße durch Mulgore nach Thunder Bluff und fahr mit dem Aufzug hinauf in die Stadt."}, [159]={node="Thunder Bluff", desc="Schalte den Flugpunkt bei Tal frei."}, [160]={hint="Ersucht in Thunder Bluff um eine Audienz beim Oberhäuptling Cairne Bloodhoof."}, [161]={npc="Cairne Bloodhoof", tgt="Cairne Bloodhoof"}, [162]={npc="Cairne Bloodhoof", tgt="Cairne Bloodhoof"}, [163]={npc="Cairne Bloodhoof", tgt="Cairne Bloodhoof", tag="Optional"}, [164]={npc="Rahauro", tgt="Rahauro", tag="Gruppe empfohlen, Optional"}, [165]={npc="Rahauro", tgt="Rahauro", tag="Gruppe empfohlen, Optional"}, [166]={hint="Bringt Thunderhorns Bericht zu Erzdruide Hamuul Runentotem in Thunder Bluff.", tag="Optional"}, [167]={npc="Erzdruide Hamuul Runetotem", tgt="Erzdruide Hamuul Runetotem", tag="Optional"}, [168]={npc="Melor Stonehoof", tgt="Melor Stonehoof"}, [169]={npc="Eylah Sunhorn", tgt="Eylah Sunhorn", desc="Kauf alle vier Materialien in einem Gang auf der Klippe und benutz zum Schluss den Weihrauch auf der Anhöhe der Jäger."}, [170]={hint="Kauft ein Kräuterbündel von Nida der Kräuterkundigen, ein Bündel Zedernzweige von Nata, der Verkäuferin für Verzauberkunstbedarf, und Sehnenfaden von Mahu, dem Verkäufer für Lederverarbeitungsbedarf, sowie Feuerstein und Zunder von Naal, dem Verkäufer für Kochbedarf.", desc="Kauf alle vier Materialien in einem Gang auf der Klippe und benutz zum Schluss den Weihrauch auf der Anhöhe der Jäger."}, [171]={npc="Eylah Sunhorn", tgt="Eylah Sunhorn", desc="Kauf alle vier Materialien in einem Gang auf der Klippe und benutz zum Schluss den Weihrauch auf der Anhöhe der Jäger."}, [172]={npc="Veren Tallstrider", tgt="Veren Tallstrider", tag="Optional", desc="Du brauchst Kürschnerei. Gib 12 Leichtes Leder ab."}, [173]={hint="Bringt Veren Tallstrider in Thunder Bluff 12 Stücke leichtes Leder.", tag="Optional", desc="Du musst Kürschnerei gelernt haben. Gib 12 Leichtes Leder ab. Gib das Material in Thunder Bluff ab. Leichtes Leder erhältst du beim Häuten niedriger Wildtiere oder durch Handel."}, [174]={npc="Veren Tallstrider", tgt="Veren Tallstrider", tag="Optional", desc="Du brauchst Kürschnerei. Gib 12 Leichtes Leder ab."}, [175]={npc="Veren Tallstrider", tgt="Veren Tallstrider", tag="Optional", desc="Du musst Lederverarbeitung gelernt haben und die Quest-Anforderung erfüllen. Bring außerdem 4 Leichtes Leder und 4 Grober Faden mit."}, [176]={text="Grober Faden", npc="Mahu", tag="Optional"}, [177]={hint="Bringt Veren Tallstrider in Thunder Bluff 4 Einheiten leichtes Leder und 4 grobe Fäden.", tag="Optional", desc="Du musst Lederverarbeitung gelernt und die Fertigkeitsstufe der Quest erreicht haben. Bring außerdem 4 Leichtes Leder und 4 Grobes Garn mit. Gib das Material in Thunder Bluff ab. Leichtes Leder erhältst du durch Häuten oder Handel. Grobes Garn kaufst du bei einem Händler."}, [178]={npc="Veren Tallstrider", tgt="Veren Tallstrider", tag="Optional", desc="Du musst Lederverarbeitung gelernt haben und die Quest-Anforderung erfüllen. Bring außerdem 4 Leichtes Leder und 4 Grober Faden mit. Die Quest kannst du auch bei Boramu annehmen (44.08, 44.89)."}, [179]={npc="Kray", tgt="Kray", tag="Optional"}, [180]={npc="Thrag Stonehoof", tgt="Thrag Stonehoof", tag="Optional"}, [181]={npc="Mot Dawnstrider", tgt="Mot Dawnstrider", tag="Optional"}, [182]={npc="Komin Winterhoof", tgt="Komin Winterhoof", tag="Optional"}, [183]={npc="Brek Stonehoof", tgt="Brek Stonehoof", tag="Optional"}, [184]={npc="Vhan", tgt="Vhan", tag="Optional"}, [185]={text="Sobald du Stufe 12 erreicht hast, geh vom Osttor Mulgores nach Camp Taurajo im Brachland."}, [186]={nodeA="{a:378}", node="Camp Taurajo", desc="Schalte den Flugpunkt bei Omusa Thunderhorn frei und folge dann der Hauptstraße nach Norden bis Crossroads."}, [187]={hint="Benutzt den Lunarstaub des Cenarius mit dem Moonkinstein, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt."}, [188]={text="Der Mondkinstein liegt direkt am Eingang des Bergpfads westlich von Camp Taurajo; flieg nach dem Sieg über Mondklaue von Camp Taurajo nach Thunder Bluff."}, [189]={npc="Turak Runetotem", tgt="Turak Runetotem"}, [190]={text="Flieg von Thunder Bluff zurück nach Camp Taurajo."}, [191]={npc="Kirge Sternhorn", tgt="Kirge Sternhorn", desc="Nimm die Quest erst an, wenn du Camp Taurajo passierst. Das Ziel ist Crossroads."}, [192]={hint="Sprecht mit Thork in Crossroads im Brachland.", desc="Nimm die Quest erst an, wenn du Camp Taurajo passierst. Das Ziel ist Crossroads."}, [193]={npc="Thork", tgt="Thork", desc="Nimm die Quest erst an, wenn du Camp Taurajo passierst. Das Ziel ist Crossroads."}, [194]={nodeA="{a:380}", node="The Crossroads", desc="Folge der Hauptstraße nach Norden nach Crossroads und schalte den Flugpunkt bei Devrak frei."}, [195]={text="Binde deinen Ruhestein im Gasthaus in Crossroads bei Gastwirt Boorand Plainswind (51.99, 29.89).", bindA="{a:380}"}, [196]={hint="Sucht Kranal Fiss im Brachland.", desc="Beginn im Dorf der Bluthufe. Ruf des Feuers setzt du in Crossroads mit der Schamanenklassenquest fort. Du kannst sie auch direkt bei Kranal annehmen."}, [197]={npc="Kranal Fiss", tgt="Kranal Fiss", desc="Beginn im Dorf der Bluthufe. Ruf des Feuers setzt du in Crossroads mit der Schamanenklassenquest fort. Du kannst sie auch direkt bei Kranal annehmen."}}},
    ["01-5"] = {name="Todesend", tips={{k="交通", text="Kommst du aus einer anderen Startzone, steig am Zeppelinturm südlich von Brill aus und folg der Straße nach Westen nach Deathknell."}, {k="提醒", text="Beginne mit Unsanftes Erwachen in der Gruft (nur Untote). Bei deiner Ankunft in Deathknell kannst du Die Hirnlosen bei Schattenpriester Sarvis (30.84, 66.20) annehmen. Bietet Sarvis die Quest nicht an, folg der Straße nach Brill.", s={{"Beginne mit Unsanftes Erwachen in der Gruft (nur Untote)", {race={"Scourge"}}}, {"Bei deiner Ankunft in Deathknell kannst du Die Hirnlosen bei Schattenpriester Sarvis (30.84, 66.20) annehmen"}, {"Bietet Sarvis die Quest nicht an, folg der Straße nach Brill"}}}, {k="提醒", text="Fehlt dir Stufe 3, töte noch ein paar Klappernde Skelette. Nimm Marlas letzter Wunsch erst ab Stufe 3 an. Sobald du Stufe 6 hast oder diesen Abschnitt beendet hast, geh nach Brill.", s={{"Fehlt dir Stufe 3, töte noch ein paar Klappernde Skelette"}, {"Nimm Marlas letzter Wunsch erst ab Stufe 3 an"}, {"Sobald du Stufe 6 hast oder diesen Abschnitt beendet hast, geh nach Brill"}}}}, danger={[1]="Im schmalen Tunnel des Nachtwebergrunds ziehst du leicht Spinnengruppen von vorn und hinten. Räum vor dem Betreten eine Runde am Eingang."}, grind={[1]={mob="Elender Zombie", note="Dichte, meist neutrale normale Mobs nördlich von Deathknell. Zieh während Die Hirnlosen auf den Stufen 1-2 jeweils einen Feind heraus."}, [2]={mob="Nachtweber", note="Dichte normale Mobs im Nachtwebergrund. In der Höhle ziehst du leicht mehrere, räum vom Eingang aus Stück für Stück. Kombiniere es mit den Höhlenquests."}, [3]={mob="Scharlachroter Initiand", note="Dichte normale Mobs im östlichen Lager des Scharlachroten Kreuzzugs. Sie sind mit Eiferern vermischt, also räum zuerst den Rand frei. Kombiniere es mit der Armband-Quest."}}, supply={[1]={npc="Schmied Rand"}, [2]={npc="Joshua Kien"}, [3]={npc="Joshua Kien"}}, steps={[1]={npc="Totengräber Mordo", tgt="Totengräber Mordo"}, [2]={npc="Schattenpriester Sarvis", tgt="Schattenpriester Sarvis"}, [3]={npc="Schattenpriester Sarvis", tgt="Schattenpriester Sarvis"}, [4]={hint="Schattenpriester Sarvis will, dass Ihr 8 hirnlose Zombies und 8 elende Zombies tötet."}, [5]={npc="Schattenpriester Sarvis", tgt="Schattenpriester Sarvis"}, [6]={npc="Novize Elreth", tgt="Novize Elreth"}, [7]={hint="Novize Elreth benötigt 6 Aasfressertatzen und 6 Nachtsaugerflügel."}, [8]={npc="Novize Elreth", tgt="Novize Elreth"}, [9]={npc="Novize Elreth", tgt="Novize Elreth"}, [10]={npc="Schattenpriester Sarvis", tgt="Schattenpriester Sarvis"}, [11]={npc="Todeswache Saltain", tgt="Todeswache Saltain"}, [12]={npc="Exekutor Arren", tgt="Exekutor Arren"}, [13]={npc="Aramis Hammerhand", tgt="Aramis Hammerhand"}, [14]={hint="Tötet 12 klappernde Skelette und kehrt zu Schattenpriester Sarvis in Deathknell zurück, wenn Ihr fertig seid."}, [15]={hint="Durchsucht Deathknell und Umgebung nach 6 Stücken aufgestöberter Ware und bringt sie zu Todeswache Saltain zurück."}, [16]={hint="Exekutor Arren will, dass Ihr 10 junge Nachtweber und 8 Nachtweber tötet."}, [17]={hint="Befreit 6 eingesponnene Opfer im Nachtwebergrund für Aramis Hammerhand in Deathknell."}, [18]={hint="Bringt Samuel Fipps' sterbliche Überreste zu Marlas Grab und kehrt dann zu Novize Elreth zurück."}, [19]={npc="Schattenpriester Sarvis", tgt="Schattenpriester Sarvis"}, [20]={npc="Todeswache Saltain", tgt="Todeswache Saltain"}, [21]={npc="Novize Elreth", tgt="Novize Elreth"}, [22]={npc="Aramis Hammerhand", tgt="Aramis Hammerhand"}, [23]={npc="Exekutor Arren", tgt="Exekutor Arren"}, [24]={npc="Exekutor Arren", tgt="Exekutor Arren"}, [25]={hint="Bringt Exekutor Arren insgesamt 12 scharlachrote Armbinden von scharlachroten Konvertiten und scharlachroten Initianden."}, [26]={npc="Exekutor Arren", tgt="Exekutor Arren"}, [27]={npc="Exekutor Arren", tgt="Exekutor Arren"}, [28]={hint="Tötet Meven Korgal, den Boten, im Lager der Kreuzzügler und kehrt danach mit allen Informationen, die Ihr findet, zu Exekutor Arren zurück."}, [29]={npc="Exekutor Arren", tgt="Exekutor Arren"}, [30]={npc="Exekutor Arren", tgt="Exekutor Arren"}, [31]={npc="Schattenpriester Sarvis", tgt="Schattenpriester Sarvis", desc="Gib zuerst Die Hirnlosen in Deathknell ab und nimm dann diese Quest an. Dieselbe Quest bekommst du auch bei Novize Elreth (30.86, 66.05)."}, [32]={hint="Lest die geweihte Schriftrolle und sprecht mit Aramis Hammerhand in der Kirche von Deathknell.", desc="Gib zuerst Die Hirnlosen in Deathknell ab und nimm dann diese Quest an."}, [33]={npc="Aramis Hammerhand", tgt="Aramis Hammerhand", desc="Gib zuerst Die Hirnlosen in Deathknell ab und nimm dann diese Quest an."}, [34]={npc="Aramis Hammerhand", tgt="Aramis Hammerhand", desc="Gib zuerst Die Hirnlosen ab. Verlass Deathknell erst, wenn du dort fertig bist."}, [35]={hint="Heal 5 verletzte Todeswachen mit Eurer Fähigkeit 'Heiliges Licht'.", desc="Gib zuerst Die Hirnlosen ab. Verlass Deathknell erst, wenn du dort fertig bist."}, [36]={npc="Aramis Hammerhand", tgt="Aramis Hammerhand", desc="Gib zuerst Die Hirnlosen ab. Verlass Deathknell erst, wenn du dort fertig bist."}, [37]={npc="Aramis Hammerhand", tgt="Aramis Hammerhand", desc="Gib zuerst Das Licht wiederentdecken ab."}, [38]={hint="Findet den verängstigten Paladin in Deathknell.", desc="Gib zuerst Das Licht wiederentdecken ab."}, [39]={npc="Aramis Hammerhand", tgt="Aramis Hammerhand", desc="Gib zuerst Das Licht wiederentdecken ab."}, [40]={npc="Aramis Hammerhand", tgt="Aramis Hammerhand", desc="Nimm sie an, bevor du Deathknell verlässt, und gib sie in Brill ab."}, [41]={npc="Schattenpriester Sarvis", tgt="Schattenpriester Sarvis", desc="Schließe Die Hirnlosen ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [42]={hint="Lest die einfache Schriftrolle und sprecht mit Dannal Stern in Deathknell.", desc="Schließe Die Hirnlosen ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [43]={npc="Dannal Stern", tgt="Dannal Stern", desc="Schließe Die Hirnlosen ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [44]={npc="Schattenpriester Sarvis", tgt="Schattenpriester Sarvis", desc="Schließe Die Hirnlosen ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [45]={hint="Lest die verschlüsselte Schriftrolle und sprecht mit David Trias in Deathknell.", desc="Schließe Die Hirnlosen ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [46]={npc="David Trias", tgt="David Trias", desc="Schließe Die Hirnlosen ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [47]={npc="Schattenpriester Sarvis", tgt="Schattenpriester Sarvis"}, [48]={hint="Lest die besudelte Schriftrolle und sprecht mit Maximillion in Deathknell."}, [49]={npc="Maximillion", tgt="Maximillion"}, [50]={npc="Venya Marthand", tgt="Venya Marthand", desc="Route in Deathknell. Horde-Hexenmeister können diese Quest annehmen."}, [51]={hint="Bringt Venya Marthand 3 Schädel eines klappernden Skeletts.", desc="Route in Deathknell. Horde-Hexenmeister können diese Quest annehmen."}, [52]={npc="Venya Marthand", tgt="Venya Marthand", desc="Route in Deathknell. Horde-Hexenmeister können diese Quest annehmen."}, [53]={npc="Schattenpriester Sarvis", tgt="Schattenpriester Sarvis", desc="Gib zuerst Die Hirnlosen ab, dann bekommst du die Schriftrolle."}, [54]={hint="Lest die geheiligte Schriftrolle und sprecht mit dem dunklen Kleriker Duesten in der Kirche von Deathknell.", desc="Gib zuerst Die Hirnlosen ab, dann bekommst du die Schriftrolle."}, [55]={npc="Dunkler Kleriker Duesten", tgt="Dunkler Kleriker Duesten", desc="Gib zuerst Die Hirnlosen ab, dann bekommst du die Schriftrolle."}, [56]={npc="Dunkler Kleriker Duesten", tgt="Dunkler Kleriker Duesten"}, [57]={npc="Dunkler Kleriker Beryl", tgt="Dunkler Kleriker Beryl"}, [58]={npc="Schattenpriester Sarvis", tgt="Schattenpriester Sarvis", desc="Gib zuerst Die Hirnlosen ab."}, [59]={hint="Lest die mit Glyphen versehene Schriftrolle und sprecht mit Isabella in der Kirche von Deathknell.", desc="Gib zuerst Die Hirnlosen ab."}, [60]={npc="Isabella", tgt="Isabella", desc="Gib zuerst Die Hirnlosen ab."}, [61]={text="Verlass Deathknell über die Oststraße und geh nach Brill."}}},
    ["01-6"] = {name="Tirisfal", nameA="Tirisfal: {a:159}", tips={{k="提醒", text="Hast du Entscheidende Informationen nicht angenommen, beginne im Gasthaus von Brill und hol dir die ersten Quests.", s={{"Hast du Entscheidende Informationen nicht angenommen, beginne im Gasthaus von Brill und hol dir die ersten Quests"}}}, {k="取捨", text="Erledige die Ziele für Scharlachrot, Spinnen und Grabkraut im Südosten in einer Runde. Kombiniere die Murlocs an der Nordküste mit den Agamand-Quests. Gib Quests in der Nähe ab und geh auf Stufe 12 nach Crossroads."}, {k="取捨", text="Kauf Grober Faden bei einem Händler für Die Kälte des Todes im Gasthaus. Fehlen dir für Häute, Bälge, Membranen noch Häute der Nordküsten-Murlocs, schließe die Quest beim nächsten Ausflug an die Küste ab."}, {k="取捨", text="Schließe beide lokalen Quests der Argentumdämmerung ab, um Die Bandarionfestung freizuschalten (nur Orcs, Trolle und Untote). Einige Folgequests der Festung gibt es nur für Untote. Willst du direkt nach Crossroads, kannst du nach den beiden lokalen Quests aufbrechen.", s={{"Schließe beide lokalen Quests der Argentumdämmerung ab, um Die Bandarionfestung freizuschalten (nur Orcs, Trolle und Untote)", {race={"Orc", "Troll", "Scourge"}}}, {"Einige Folgequests der Festung gibt es nur für Untote", {race={"Scourge"}}}, {"Willst du direkt nach Crossroads, kannst du nach den beiden lokalen Quests aufbrechen"}}}, {k="提醒", text="Unter Stufe 12? Führ die Quests Krieg mit dem Scharlachroten Kreuzzug, Die Familiengruft oder Argentumdämmerung Der Argentumabgesandte, Der Kult der Verdammten und Überreste des Krieges aus, je nach Verfügbarkeit und Standort.", s={{"Unter Stufe 12?"}, {"Führ die Quests Krieg mit dem Scharlachroten Kreuzzug, Die Familiengruft oder Argentumdämmerung Der Argentumabgesandte, Der Kult der Verdammten und Überreste des Krieges aus, je nach Verfügbarkeit und Standort"}}}}, danger={[1]="Auf dem südöstlichen Friedhof treiben sich Blutzombies und umherstreifende Geister herum, du wirst leicht von zwei Seiten gepackt. Räum am Friedhofsrand und halte dir den Rückweg frei."}, grind={[1]={mob="Scharlachroter Missionar", note="Verstreute normale Mobs mit Zauberwirkern südwestlich von Brill. Zieh sie vom Lagerrand einzeln heran, während du die ersten Quests des Scharlachroten Kreuzzugs machst."}, [2]={mob="Wandernder Geist", note="Auf dem südöstlichen Friedhof tummeln sich normale Mobs mit Blutzombies. Achte auf Patrouillen. Kombiniere Patrouille zur Rückendeckung mit Grabkraut."}, [3]={mob="Dunkler Neophyt", note="Dichte normale Mobs, gemischt mit Dunklen Vollstreckern, nahe den Argentumdämmerung-Quests im Südosten. Am Lagerrand lassen sie sich leichter einzeln ziehen. Farme ab Stufe 11 bis Stufe 12."}}, supply={[1]={npc="Gastwirtin Renee"}, [2]={npc="Abe Winters"}, [3]={npc="Gastwirtin Renee"}, [4]={npc="Mrs. Winters"}, [5]={npc="Doras"}}, steps={[1]={npc="Todeswache Simmer", tgt="Todeswache Simmer"}, [2]={npc="Gordo", tgt="Gordo"}, [3]={hint="Stehlt 10 Kürbisse vom Gehöft im Westen, direkt nördlich von Deathknell und bringt sie zu Apotheker Johann nach Brill."}, [4]={hint="Sammelt 3 Düsterkräuter und bringt sie zu Jungapotheker Holland auf den Brill-Friedhof."}, [5]={npc="Exekutor Zygand", tgt="Exekutor Zygand"}, [6]={npc="Exekutor Zygand", tgt="Exekutor Zygand"}, [7]={npc="Exekutor Zygand", tgt="Exekutor Zygand"}, [8]={npc="Exekutor Zygand", tgt="Exekutor Zygand"}, [9]={npc="Apotheker Johaan", tgt="Apotheker Johaan"}, [10]={npc="Jungapotheker Holland", tgt="Jungapotheker Holland"}, [11]={hint="Folgt der Straße nach Osten aus Deathknell heraus, um nach Brill zu gelangen. Meldet Euch bei Shari Stilwell, um Eure Ausbildung fortzusetzen."}, [12]={npc="Shari Stilwell", tgt="Shari Stilwell"}, [13]={npc="Dunkler Kleriker Beryl", tgt="Dunkler Kleriker Beryl", desc="Trainiere zuerst Geringes Heilen (Rang 2) und Machtwort: Seelenstärke."}, [14]={hint="Findet die Todeswache Kel und heilt seine Wunden mit Hilfe von 'Geringes Heilen' (Rang 2). Belegt ihn danach mit 'Machtwort: Seelenstärke' und kehrt zum dunklen Kleriker Beryl in Brill zurück.", desc="Trainiere zuerst Geringes Heilen (Rang 2) und Machtwort: Seelenstärke."}, [15]={npc="Dunkler Kleriker Beryl", tgt="Dunkler Kleriker Beryl", desc="Trainiere zuerst Geringes Heilen (Rang 2) und Machtwort: Seelenstärke."}, [16]={npc="Eleanor Shackleton", tgt="Eleanor Shackleton"}, [17]={hint="Setzt Euch an Eleanors einfaches Lagerfeuer und wartet, bis Ihr den verbesserten Ruhebonus erhalten habt."}, [18]={npc="Eleanor Shackleton", tgt="Eleanor Shackleton"}, [19]={npc="Eleanor Shackleton", tgt="Eleanor Shackleton", tag="Optional"}, [20]={npc="Eleanor Shackleton", tgt="Eleanor Shackleton", text="Grundlagen des Zeltens (beliebiger Beruf)", tag="Optional"}, [21]={npc="Jungapotheker Holland", tgt="Jungapotheker Holland"}, [22]={text="Bind deinen Ruhestein in Brill bei Gastwirtin Renee (61.72, 52.05).", bindA="{a:159}"}, [23]={hint="Sprecht mit William Pickman in Brill, um das Kochen zu erlernen.", tag="Optional"}, [24]={npc="William Pickman", tgt="William Pickman", tag="Optional"}, [25]={npc="Carolai Anise", tgt="Carolai Anise", tag="Optional"}, [26]={npc="Vance Undergloom", tgt="Vance Undergloom", tag="Optional"}, [27]={npc="Schwester Neela", tgt="Schwester Neela", tag="Optional"}, [28]={npc="Clyde Kellen", tgt="Clyde Kellen", tag="Optional"}, [29]={npc="Faruza", tgt="Faruza", tag="Optional"}, [30]={npc="Bowen Brisboise", tgt="Bowen Brisboise", tag="Optional"}, [31]={npc="Apotheker Johaan", tgt="Apotheker Johaan"}, [32]={npc="Gefangener Scharlachroter Zelot", tgt="Gefangener Scharlachroter Zelot"}, [33]={npc="Todeswache Dillinger", tgt="Todeswache Dillinger"}, [34]={npc="Magistrat Sevren", tgt="Magistrat Sevren"}, [35]={npc="Apotheker Johaan", tgt="Apotheker Johaan"}, [36]={npc="GESUCHT!", npcObj=true}, [37]={text="Außerhalb von Brill und im Westen beim Scharlachroten Kreuzzug"}, [38]={hint="Bringt Todeswache Dillinger in Brill 7 eitrige Klauen."}, [39]={hint="Tötet Grabräuber der Moderfelle und Bastarde der Moderfelle."}, [40]={hint="Apotheker Johaan in der Stadt Brill möchte, dass Ihr 5 Phiolen Schattenhundblut sammelt."}, [41]={hint="Sammelt 10 Verdammniskräuter und bringt sie zu Jungapotheker Holland."}, [42]={hint="Exekutor Zygand von Brill verlangt, dass Ihr 10 Scharlachrote Krieger tötet."}, [43]={hint="Bestraft 5 Todeswachen für Exekutor Zygand."}, [44]={hint="Besorgt die Berichte von Todeswache Dillinger, Todeswache Kristof und Gordo für Exekutor Zygand."}, [45]={npc="Todeswache Dillinger", tgt="Todeswache Dillinger"}, [46]={npc="Todeswache Dillinger", tgt="Todeswache Dillinger"}, [47]={npc="Jungapotheker Holland", tgt="Jungapotheker Holland"}, [48]={npc="Jungapotheker Holland", tgt="Jungapotheker Holland"}, [49]={npc="Apotheker Johaan", tgt="Apotheker Johaan"}, [50]={npc="Apotheker Johaan", tgt="Apotheker Johaan"}, [51]={npc="Exekutor Zygand", tgt="Exekutor Zygand"}, [52]={npc="Exekutor Zygand", tgt="Exekutor Zygand"}, [53]={npc="Exekutor Zygand", tgt="Exekutor Zygand"}, [54]={npc="Exekutor Zygand", tgt="Exekutor Zygand"}, [55]={npc="Todeswache Burgess", tgt="Todeswache Burgess"}, [56]={npc="Magistrat Sevren", tgt="Magistrat Sevren"}, [57]={npc="Magistrat Sevren", tgt="Magistrat Sevren"}, [58]={text="Murlocs an der Nordküste, Madenauge und Agamands Mühlen"}, [59]={npc="Coleman Farthing", tgt="Coleman Farthing"}, [60]={npc="Coleman Farthing", tgt="Coleman Farthing"}, [61]={npc="Gretchen Dedmar", tgt="Gretchen Dedmar"}, [62]={hint="Apotheker Johaan in der Stadt Brill benötigt 5 Finsterflossenschuppen von den Murlocs in Tirisfal."}, [63]={hint="Tötet Madenauge und kehrt dann mit seiner Tatze zu Exekutor Zygand nach Brill zurück, um eine Belohnung zu erhalten."}, [64]={hint="Sammelt 5 schartige Rippen sowie 3 geschwärzte Schädel und kehrt dann zu Todeswache Dillinger nach Brill zurück."}, [65]={hint="Bringt Coleman Farthing in Brill Gregors Überreste, Nissas Überreste und Thurmans Überreste."}, [66]={hint="Erschlagt Devlin Agamand und bringt Devlins Überreste zu Coleman Farthing nach Brill."}, [67]={npc="Ein Brief an Yvette", npcObj=true, tag="Nur wenn es droppt, Optional"}, [68]={npc="Apotheker Johaan", tgt="Apotheker Johaan"}, [69]={npc="Exekutor Zygand", tgt="Exekutor Zygand"}, [70]={npc="Todeswache Dillinger", tgt="Todeswache Dillinger"}, [71]={npc="Coleman Farthing", tgt="Coleman Farthing"}, [72]={npc="Coleman Farthing", tgt="Coleman Farthing"}, [73]={hint="Findet Yvette Farthing und bringt Ihr den Brief von Thurman Agamand.", tag="Optional"}, [74]={npc="Yvette Farthing", tgt="Yvette Farthing", tag="Optional"}, [75]={npc="Coleman Farthing", tgt="Coleman Farthing"}, [76]={npc="Magistrat Sevren", tgt="Magistrat Sevren"}, [77]={npc="Apotheker Johaan", tgt="Apotheker Johaan"}, [78]={text="Südliches Lager des Scharlachroten Kreuzzugs, südöstlicher Außenposten und Balnirs Bauernhof"}, [79]={hint="Exekutor Zygand in Brill möchte, dass Ihr Captain Perrine, 3 Scharlachrote Zeloten und 3 Scharlachrote Missionare tötet."}, [80]={npc="Exekutor Zygand", tgt="Exekutor Zygand"}, [81]={npc="Exekutor Zygand", tgt="Exekutor Zygand"}, [82]={text="Grober Faden", npc="Abigail Shiel"}, [83]={npc="Todeswache Linnea", tgt="Todeswache Linnea"}, [84]={npc="Todeswache Linnea", tgt="Todeswache Linnea"}, [85]={npc="Todeswache Linnea", tgt="Todeswache Linnea"}, [86]={npc="Shelene Rhobart", tgt="Shelene Rhobart", desc="Du kannst dieselbe Quest bei Todeswache Linnea annehmen (65.49, 60.25)."}, [87]={hint="Tötet 8 blutende Schrecken und 8 wandernde Geister und meldet Euch dann wieder bei Linnea in ihrem Lager."}, [88]={hint="Sammelt 5 Grabkräuter und bringt sie zu Jungapotheker Holland."}, [89]={hint="Apotheker Johaan in der Stadt Brill möchte, dass Ihr ihm 4 Proben vom Gift eines heimtückischen Nachtwebers bringt."}, [90]={hint="Exekutor Zygand in Brill hat Euch damit beauftragt, Captain Vachon und 5 Scharlachrote Ordensmitglieder zu erschlagen."}, [91]={hint="Bringt Todeswache Burgess in Brill 10 scharlachrote Insignienringe."}, [92]={hint="Bringt Gretchen Dedmar in Brill fünf Nachtsaugerpelze und etwas groben Faden."}, [93]={npc="Todeswache Linnea", tgt="Todeswache Linnea"}, [94]={hint="Bringt Shelene Rhobart 8 Nachtsaugerflügelmembranen, 6 Schattenhundbälge und 3 Häute eines Murlocs der Finsterflossen."}, [95]={npc="Shelene Rhobart", tgt="Shelene Rhobart"}, [96]={npc="Shelene Rhobart", tgt="Shelene Rhobart", tag="Optional"}, [97]={npc="Rand Rhobart", tgt="Rand Rhobart", tag="Optional"}, [98]={npc="Magistrat Sevren", tgt="Magistrat Sevren"}, [99]={npc="Jungapotheker Holland", tgt="Jungapotheker Holland"}, [100]={npc="Gretchen Dedmar", tgt="Gretchen Dedmar"}, [101]={npc="Apotheker Johaan", tgt="Apotheker Johaan"}, [102]={npc="Apotheker Johaan", tgt="Apotheker Johaan"}, [103]={npc="Gefangener Gebirgsjäger", tgt="Gefangener Gebirgsjäger"}, [104]={npc="Todeswache Burgess", tgt="Todeswache Burgess"}, [105]={npc="Exekutor Zygand", tgt="Exekutor Zygand"}, [106]={npc="Exekutor Zygand", tgt="Exekutor Zygand", tag="Optional", desc="Am weitesten vom Dorf entfernt. Geh nur hin, wenn du noch unter Stufe 12 bist."}, [107]={hint="Exekutor Zygand in der Stadt Brill möchte, dass Ihr Captain Melrache und seine beiden Leibwachen ermordet.", tag="Optional", desc="Am weitesten vom Dorf entfernt. Geh nur hin, wenn du noch unter Stufe 12 bist."}, [108]={npc="Exekutor Zygand", tgt="Exekutor Zygand", tag="Optional", desc="Am weitesten vom Dorf entfernt. Geh nur hin, wenn du noch unter Stufe 12 bist."}, [109]={npc="Magistrat Sevren", tgt="Magistrat Sevren", desc="Nimm die Quest an, nachdem du beide Agamand-Quests abgeschlossen hast.", star={"Dunkelholzstab", {"MAGE", "PRIEST", "WARLOCK", "DRUID", "SHAMAN"}}}, [110]={hint="Tötet 8 Klagende Vorfahren und 8 Faulende Vorfahren.", desc="Nimm die Quest an, nachdem du beide Agamand-Quests abgeschlossen hast."}, [111]={npc="Magistrat Sevren", tgt="Magistrat Sevren", desc="Nimm die Quest an, nachdem du beide Agamand-Quests abgeschlossen hast.", star={"Dunkelholzstab", {"MAGE", "PRIEST", "WARLOCK", "DRUID", "SHAMAN"}}}, [112]={text="Extra EP oder neue Quests vor Stufe 12"}, [113]={npc="Todeswache Terrence", tgt="Todeswache Terrence"}, [114]={hint="Findet das Mitglied der Argentumdämmerung in der Nähe des Eingangs von Undercity."}, [115]={npc="Hadric Harlson", tgt="Hadric Harlson"}, [116]={npc="Hadric Harlson", tgt="Hadric Harlson"}, [117]={npc="Hadric Harlson", tgt="Hadric Harlson"}, [118]={hint="Tötet 8 dunkle Neophyten und 8 dunkle Vollstrecker in Tirisfal."}, [119]={hint="Sammelt 12 nekrotische Kristallfragmente in Tirisfal."}, [120]={npc="Hadric Harlson", tgt="Hadric Harlson"}, [121]={npc="Hadric Harlson", tgt="Hadric Harlson"}, [122]={npc="Hadric Harlson", tgt="Hadric Harlson", tag="Optional", desc="Dies führt dich vom südöstlichen Außenposten weg. Überspring es, wenn du es eilig hast."}, [123]={hint="Trefft Leonid Barthalomew in der Bandarionfestung in Tirisfal.", tag="Optional", desc="Dies führt dich vom südöstlichen Außenposten weg. Überspring es, wenn du es eilig hast."}, [124]={npc="Leonid Barthalomew der Geachtete", tgt="Leonid Barthalomew der Geachtete", tag="Optional", desc="Dies führt dich vom südöstlichen Außenposten weg. Überspring es, wenn du es eilig hast."}, [125]={npc="Todeswache Linnea", tgt="Todeswache Linnea", tag="Gruppe empfohlen, Optional", desc="Elite. Überspring es, wenn du nicht in einer Gruppe bist."}, [126]={hint="Bringt Reißers Herz zu Todeswache Linnea.", tag="Gruppe empfohlen, Optional", desc="Elite. Überspring es, wenn du nicht in einer Gruppe bist."}, [127]={npc="Todeswache Linnea", tgt="Todeswache Linnea", tag="Gruppe empfohlen, Optional", desc="Elite. Überspring es, wenn du nicht in einer Gruppe bist."}, [128]={npc="Apotheker Johaan", tgt="Apotheker Johaan", desc="Gib sie ab, wenn du auf Stufe 16 nach Silberwald gehst."}, [129]={npc="Shari Stilwell", tgt="Shari Stilwell", desc="Nimm die Quest an, wenn du auf Stufe 8 nach Brill zurückkehrst."}, [130]={hint="Findet die Bandarionfestung und me