    [899] = {n="Von Hass zerfressen", d="Bringt Mankrik in Crossroads 60 Stacheleberhauer der Borstennacken.", tgo={{"Jäger der Borstennacken", "Wassersucher der Borstennacken", "Dornenwirker der Borstennacken", "Geomant der Borstennacken", "Bristleback Defender", "Bristleback Mystic"}}},
    [900] = {n="Samophlang", d="Schließt das Treibstoffzufuhrventil, das Regelventil und das Hauptsteuerventil, und benutzt dann noch einmal die Steuerkonsole.", objs={"Hauptsteuerventil", "Treibstoffzufuhrventil", "Regelventil"}},
    [901] = {n="Samophlang", d="Besorgt Euch bei Tüftler Sniggles den Konsolenschlüssel, um damit die Steuerkonsole zu öffnen.", tgo={{"Tüftler Sniggles"}}},
