    [914] = {n="Anführer der Giftzähne", d="Bringt die Edelsteine von Kobrahn, Anacondra, Pythas und Serpentis nach Thunder Bluff zu Nara Wildmane.", tgo={{"Lord Kobrahn", "Schlangengestalt von Kobrahn"}, {"Lady Anacondra"}, {"Lord Pythas"}, {"Lord Serpentis"}}, star={"Mondsichelstab", {"MAGE", "PRIEST", "WARLOCK", "DRUID", "SHAMAN"}}},
    [959] = {n="Ärger auf den Docks", d="Kranführer Bigglefuzz in Ratchet möchte, dass Ihr Zausel dem Verrückten, der sich in den Höhlen des Wehklagens versteckt, die Flasche mit 99-jährigem Portwein wieder abnehmt.", tgo={{"Zausel der Verrückte"}}},
    [962] = {n="Schlangenflaum", d="Die Apothekerin Zamah in Thunder Bluff möchte, dass Ihr zehn Schlangenflaum für sie sammelt.", objs={"Schlangenflaum"}},
    [964] = {n="Skelettfragmente", d="Bringt 15 Skelettfragmente zu Apotheker Dithers am Bollwerk, Westliche Pestländer.", tgo={{"Skelettschinder", "Skelettzauberhexer", "Skelettschrecker", "Skeletthenker", "Skelettkriegsherr", "Skelettakolyth", "Skeletal Magelord"}}},
    [974] = {n="Die Quelle finden", d="Krakle im Un'Goro Krater möchte, dass Ihr den heißesten Bereich des Feuerfedergrats findet.\nImmer, wenn Ihr eine heiße Stelle findet, klickt Ihr das Thermometer mit der rechten Maustaste an, um die Temperatur zu überprüfen. Sucht, bis Ihr die heißeste Stelle gefunden habt.", objs={"Feuerfedergrat - Heiße Stelle"}},
    [977] = {n="Sind wir endlich da, Yeti?", d="Sammelt 2 makellose Yetihörner für Umi Rumplesnicker in Everlook.", tgo={{"Eisdistelmatriarchin", "Eisdistelpatriarch"}}},
    [980] = {n="Die neuen Quellen", d="Reist nach Winterspring und sprecht mit Donova Snowden."},
    [992] = {n="Gadgetzan Wassersondierung", d="Benutzt den unangezapften Wünschelrutenapparat in der Nähe des Teichs bei der Sandsorrow-Wache. Bringt den angezapften Wünschelrutenapparat zum Leitenden Feldmesser Fizzledowser nach Gadgetzan zurück, wenn Ihr die Probe entnommen habt.", objs={"Wasserloch von Sandsorrowwatch"}},
    [1000] = {n="Die neue Grenze", d="Sprecht auf der Anhöhe der Ältesten in Thunder Bluff mit dem Erzdruiden Hamuul Runetotem über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor."},
