    [8412] = {n="Geistertotem", d="Bringt Bath'rah dem Windbehüter die Komponenten für das Geistertotem.", tgo={{"Aasgeier", "Aaslauerer", "Giftnebellauerer", "Seuchenlauerer", "Rotting Condor", "Pestschwingengeier"}, {"Aasgeier", "Kranker Schwarzbär", "Kranker Grizzly", "Rotting Condor", "Pestschwingengeier"}}},
    [8413] = {n="Die Macht des Voodoos", d="Bringt Bath'rah dem Windbehüter die Voodoofedern.", tgo={{"Schlitzer", "Zul'Lor", "Schlitzer"}, {"Hukku", "Mijan", "Hukku"}, {"Zolo", "Loro", "Loro"}}, star={"Entzückter Wassergeist", {"SHAMAN"}}},
    [8417] = {n="Ein geplagter Geist", d="Sprecht mit dem gefallenen Helden der Horde am Eingang zu den verwüsteten Landen."},
    [8420] = {n="Heiß und brennend", d="Bringt ein Stück Teufelsstoff zu Impsy im Teufelswald.", tgo={{"Teufelsjäger", "Wachposten der Teufelswache", "Satyr der Legashi", "Schurke der Legashi", "Höllenrufer der Legashi", "Meister Gräuelbart", "Jadefeuerschurke", "Jadefeuerschwindler"}}},
