    [92462] = {n="Befallsbegutachtung", d="Tötet 8 lästige Zirrusfliegen im Thendalhain.", tgo={{"Lästige Zirrusfliege"}}},
    [92463] = {n="Die Zirrusfliegenkönigin", d="Vernichtet die Zirrusfliegenkönigin im Thendalhain.", tgo={{"Zirrusfliegenkönigin"}}},
    [92464] = {n="Unruhige Elemente", d="Sprecht mit Yala Windwächter im Thendalhain."},
    [92465] = {n="Aufrührer", d="Tötet 6 aufgewühlte Winde und 7 Konvertiten der Al'Aketh im Thendalhain.", tgo={{"Konvertit der Al'Aketh"}, {"Aufgewühlte Winde"}}},
    [92466] = {n="Ruf der Erde", d="Bringt Windformer Boro ein Siegel von Akir.", tgo={{"Schläger der Al'Aketh", "Konvertit der Al'Aketh", "Neophyt der Al'Aketh", "Hohepriesterin Lorthuna", "Himmelspriester Aanders", "Kommandantin Belguilos"}}},
    [92467] = {n="Ruf der Erde", d="Sucht die Anhöhe der Geister und trinkt das Erdsapta."},
    [92468] = {n="Ruf der Erde", d="Bringt den Rohquarz zu Windformer Boro im Thendalhain."},
    [92469] = {n="Rückkehr zu Rorian", d="Berichtet Rorian dem Tagsucher im Thendalhain von den Al'Aketh."},
    [92470] = {n="Widerwärtige Matriarchin", d="Tötet 8 Urseraplünderer und beschafft den Kopf ihrer Höhlenmutter Urs'anah im Thendalhain.", tgo={{"Urseraplünderer"}, {"Urs'anah"}}},
    [92471] = {n="Aetheen von den Winden", d="Sprecht mit Aetheen von den Winden im Thendalhain."},
    [92472] = {n="Der nächste Schritt", d="Meldet Euch bei Wachtmeisterin Aonda in Shen'dar."},
    [92473] = {n="Aggressive Übergriffe", d="Sammelt 6 magere Urseraklauen von mageren Ursera im Thendalhain.", tgo={{"Magerer Ursera"}}},
    [92474] = {n="Fallen mit Stil", d="Springt von der Spitze des Wachturms im Thendalhain und verlangsamt Euren Fall mit Eurer Fähigkeit \"Luftwandeln\"."},
    [92482] = {n="Der Weg des Jägers", d="Lest die gekritzelte Notiz und sprecht dann mit Tai'ree Farsight im Thendalhain."},
    [92483] = {n="Zu Hause in den Schatten", d="Lest die einfache Notiz und sprecht dann mit Akeri Duskblade im Wachturm im Thendalhain."},
    [92484] = {n="Hingabe zu den Elementen", d="Untersucht den summenden Rückrufkristall und sprecht dann mit Windformer Boro im Thendalhain."},
    [92485] = {n="Ein Schüler der Natur", d="Lest das gefaltete Pergament und sprecht dann mit Xyton Silberwind im Thendalhain."},
    [92500] = {n="Ein Stück des Himmels", d="Findet das Juwel des Horizonts in einem Nest der Harpyien der Wurmschwingen und bringt es zu Ketharas."},
    [92514] = {n="Willkommen in Shen'dar", d="Sprecht mit Illaya Amberwind und Coriella Calmbreeze in Shen'dar.", tgo={{"Illaya Amberwind"}, {"Coriella Calmbreeze"}}},
    [92515] = {n="Das Problem mit Rudelkrallen", d="Sammelt 10 Rudelkrallenpelze von Rudelkrallen im Shen'darhochland.", tgo={{"Rudelkralle"}}, star={"Einfacher Lederranzen"}},
    [92516] = {n="Hippogryphenschikane", d="Tötet 8 junge Hippogryphen, 6 Hippogryphenbeschützer und eine Hippogryphenmatriarchin im Shen'darhochland.", tgo={{"Junger Hippogryph"}, {"Hippogryphenbeschützer"}, {"Hippogryphenmatriarchin"}}},
    [92517] = {n="Das kriminelle Element", d="Tötet 10 Hochlandbanditen und ihren Anführer \"Übelwind\" Bennic im Shen'darhochland.", tgo={{"Hochlandbandit"}, {"Übelwind Bennic"}}},
