    [92544] = {n="Schläger der Al'Aketh", d="Tötet 6 Schläger der Al'Aketh, 4 Neophyten der Al'Aketh und Malduko Cloudcrush im Thendalhain.", tgo={{"Schläger der Al'Aketh"}, {"Neophyt der Al'Aketh"}, {"Malduko Cloudcrush"}}},
    [92550] = {n="Verwüstung im Hochland", d="Reist in die Ruinen von Falaath und tötet 6 Sturmrufer der Al'Aketh, 4 lebendige Blitze und holt Euch den Kopf von Kommandant Cyclas.", tgo={{"Sturmrufer der Al'Aketh"}, {"Lebendiger Blitz"}, {"Kommandant Cyclas"}}},
    [92551] = {n="Gestohlene Versorgungsgüter", d="Sammelt 10 Pakete gestohlener Vorräte der Shen'dar in Falaath im Shen'darhochland.", tgo={{"Sturmrufer der Al'Aketh", "Heiler der Al'Aketh", "Tel'daeor der Sturmsprecher", "Sturmheilerin Delanea"}}},
    [92553] = {n="Die Vorratskammern auffüllen", d="Sammelt 3 kleine Eier und 8 Stück Schreiterfleisch von den Kreaturen im Shen'darhochland.", tgo={{"Großer Fleischreißer", "Junger Fleischreißer", "Terrorkondor", "Fleischreißer", "Bergbussard", "Strigideule", "Strigidkreischer", "Strigidjäger"}, {"Schreitergelegemutter", "Waldschreiterjunges", "Waldschreiter", "Riesiger Waldschreiter", "Großer Ebenenschreiter", "Störrischer Ebenenschreiter", "Flüchtiger Ebenenschreiter", "Windschreiter"}}},
    [92579] = {n="Nach Valanaar", d="Bringt Aondas schriftlichen Bericht zu Valennia Stormfist in Valanaar."},
    [92592] = {n="Ein für alle Mal tot", d="Setzt die Fackel des Überlebenden beim Knochenhaufen ein und sammelt dann das Amulett des Wiedererweckers ein.", tgo={{"Wiedererwecker der Geißel"}}},
    [92594] = {n="Zunder im Zaum", d="Zerstört 15 besudelte Gebüsche für Kaylaena Springwhisper bei der Werkstatt im Besudelten Vorgebirge.", tgo={{"Besudeltes Gebüsch"}}},
