    [92640] = {n="Verzweifelte Zeiten", d="Sprecht mit Valanaar Stormfist in Valanaar und folgt ihren Anweisungen.", tgo={{"Valennia Stormfist"}, {"Ayessa Dawnsinger"}, {"Elaadrin Evengale"}}},
    [92642] = {n="Störung der Logistik", d="Tötet 4 Heiler der Al'Aketh und 8 Muskelprotze der Al'Aketh im Böenbeerentiefland.", tgo={{"Heiler der Al'Aketh"}, {"Muskelprotz der Al'Aketh"}}},
    [92643] = {n="Der Abtrünnige", d="Findet den abtrünnigen Kultisten im Haus im Hochland nordwestlich von Valanaar.", tgo={{}, {"Toter Kultist"}}},
    [92644] = {n="Bedauerliche Neuigkeiten", d="Überbringt den leuchtenden Kristall an Talaanis Shadowsong in Valanaar."},
    [92645] = {n="Die Brecherin brechen", d="Tötet Kommandantin Belguilos im Böenbeerentiefland.", tgo={{"Kommandantin Belguilos"}}},
