    [92693] = {n="Standhaft bleiben", d="Sprecht mit Aamelia Windfield, wenn Ihr bereit seid, den Banditenanführer zu konfrontieren.", tgo={{"Aamelia Windfield"}, {"Ferauu der Knüttel"}}},
    [92698] = {n="Was ist meine Funktion?", d="Sprecht mit Aamelia Windfield über das fehlerhafte Wirbelsturmkonstrukt."},
    [92700] = {n="Die hohe Himmelseherin", d="Findet Ayessa Dawnsinger in Valanaar."},
    [92703] = {n="Überbringung der Neuigkeiten", d="Sprecht mit lvarion Windfield in Valanaar."},
    [92706] = {n="GESUCHT: Bruuz", d="Bringt Bruuz' Rückenflosse zu Gazlowe in Ratchet.", tgo={{"Bruuz"}}},
    [92708] = {n="Ein großes Abenteuer", d="Hört Euch an, was Ayessa Dawnsinger zu sagen hat.", tgo={{"Ayessa Dawnsinger"}}},
    [92833] = {n="Ve'hans Ende", d="Verwendet den Stab des Berges, um Ve'han Klauengriff seine gestohlene Macht zu nehmen, und vernichtet ihn.", tgo={{"Ve'han Talongrasp"}}},
    [92871] = {n="Für Zephras", d="Meldet Euch bei Valennia Stormfist und versichert ihr, dass die Windformer ihr im Kampf gegen die Al'Aketh zur Seite stehen."},
