    [93407] = {n="Ein Dorn in der Tatze", d="Findet Dornensamen in den Wäldern am Gipfel von Hyjal und bringt sie zu Tiala Whitemane zurück."},
    [93429] = {n="Blut meines Blutes", d="Tötet 10 Verirrte im Fallow Heiligtum."},
