    [93617] = {n="Jäger und Gejagte", d="Bringt die Hirsche davon ab, sich wie Raubtiere aufzuführen.", tgo={{"Räuberischer Hyjalhirsch"}}},
    [93680] = {n="Schlüssel zur Stadt", d="Holt den Kanalisationsschlüssel von Dalaran für Magus Wordeen Voidglare in Tarrens Mühle."},
    [93735] = {n="Das kaputte Konstrukt", d="Findet Riaani Nightwind im westlichen Teil von Valanaar."},
    [93736] = {n="Unerwünschte Geister", d="Sammelt 10 Windhüllenessenzen von Windhüllen im Schattenwindwald.", tgo={{"Windhülle"}}},
    [93737] = {n="Das kaputte Konstrukt", d="Sprecht mit Rianni Nightwind und hört, was er zu sagen hat.", tgo={{"Riaani Nightwind"}, {}, {}, {}}, objs={"Konstruktteile"}},
    [93738] = {n="Das kaputte Konstrukt", d="Erstattet Ayessa Dawnsinger in Valanaar Bericht."},
    [93740] = {n="Blut für Blut", d="Sammelt 10 Windsteinamulette der Al'Aketh von toten Kultisten im Böenbeerentiefland.", tgo={{"Sturmjäger der Al'Aketh", "Fußsoldat der Al'Aketh", "Wächter der Al'Aketh", "Geistrufer der Al'Aketh", "Himmelspriesterin der Al'Aketh", "Klingenmeister der Al'Aketh", "Ehrenwache der Al'Aketh", "Prediger der Al'Aketh"}}},
    [93746] = {n="Eine entschiedene Reaktion", d="Konfrontiert Belathaan Brightwish auf der Straße zum Schrein von Akir.", tgo={{"Belathaan Brightwish"}}},
    [93747] = {n="Von Gewalt zu Vegetation", d="Pflanzt die verzauberten Samen in der Nähe der zerstörten Balliste, des zerstörten Katapults und der zerstörten Flugmaschine."},
    [93759] = {n="Die Fülle der Natur", d="Sammelt 2 Stücke Wildfleisch von unbefleckten Hyjalhirschen und 6 scharlachrote Wurmknollen für den Eintopf des Einsiedlers.", tgo={{"Hyjalhirsch", "Räuberischer Hyjalhirsch"}, {}}},
    [93773] = {n="Der Pakt", d="Erstattet Ketharas auf dem Hyjal Bericht."},
    [93786] = {n="Eine blutige Botschaft", d="Tötet 12 Landarbeiter aus Wiesenbach und kehrt dann zu Krom'rosh zurück, um ihm von Eurem Erfolg zu berichten.", tgo={{"Landarbeiter von Wiesenbach"}}},
    [93787] = {n="Das Füllhorn plündern", d="Stehlt 6 Futterbeutel von der Allianzfarm in Wiesenbach und kehrt zu Krom'rosh zurück."},
    [93788] = {n="Geliehene Klingen", d="Erbeutet 10 Äxte des Holzarbeiters von den Holzfällern bei Turners Holzfällerlager für Kreza Darkthorn in Rog'mar.", tgo={{"Holzfäller von Turners Mühle"}}},
    [93836] = {n="Das Schicksal Zephras'", d="Sprecht mit Talaanis Shadowsong in Valanaar.", tgo={{"Talaanis Shadowsong"}}},
    [93848] = {n="Gute Arbeit", d="Kehrt zu Ketharas zurück und berichtet ihm von den Ereignissen am Gipfel der Ewigkeit."},
    [93926] = {n="Die Westwacht", d="Findet Friedensbewahrer Vaaniel im westlichen Wachturm.", tgo={{"Friedensbewahrer Vaaniel"}}},
    [93927] = {n="Eine letzte Bitte", d="Hebt die Notiz auf, die Ihr bei dem toten Friedensbewahrer gefunden habt, um über Eure nächsten Schritte zu entscheiden.", tgo={{"Himmelspriester Aanders"}, {}, {}, {}}, objs={"Blutige Notiz", "Raani Windgazer", "Arvensus Shadowsong"}},
    [93948] = {n="Überbringt das Siegel", d="Überbringt das Siegel der Familie Shadowsong an Talaanis Shadowsong in Valanaar."},
    [93949] = {n="Geplagt", d="Tötet Himmelshüpfer in Valanaar, bis Ihr 8 verzauberte Himmelshüpfer eliminiert habt.", tgo={{"Himmelshüpfer"}}},
    [93951] = {n="Ein wenig Schönheit", d="Sammelt 8 Hippogryphendaunen im Shen'darhochland.", objs={"Hippogryphendaunen"}},
    [93952] = {n="Gestärktes Gleichgewicht", d="Bezwingt 9 Höhlenwächter der Totenwaldfelle und kehrt zu Brerufa zurück.", tgo={{"Höhlenwächter der Totenwaldfelle"}}},
    [93958] = {n="Das Innere Sanktum", d="Sprecht mit Valanaar Stormfist im inneren Sanktum beim Schrein von Akir."},
    [93976] = {n="Die Goblinhändlerin", d="Bringt die Klinge zu Kreza Darkthorns Bekannten bei den Docks östlich von Rog'mar."},
    [94003] = {n="Das Bollwerk der Himmelsbrecher", d="Holt das Bollwerk der Himmelsbrecher von Zaal Stormshield am Schrein von Akir zurück.", tgo={{"Zaal Stormshield"}}, star={"Sturmgeschmiedeter Beschützer", {"WARRIOR"}}},
    [94006] = {n="Der große Urserageist", d="Sprecht mit Urs'endris in der Nähe der Wasserfälle im Nordosten von Valanaar."},
    [94007] = {n="Die Bestie zähmen", d="Meldet Euch bei Quel'ana Quickgale in Valanaar."},
    [94013] = {n="Die Bestie zähmen", d="Benutzt die Zähmerrute, um einen Vuldrenalpha im Böenbeerentiefland zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmerrute dann zu Quel'ana Quickgale in Valanaar zurück.", tgo={{"Vuldrenalpha"}}},
    [94050] = {n="Die Bestie abrichten", d="Sprecht mit Quel'dora Quickgale in Valanaar."},
    [94411] = {n="Einmischende Magier", d="Tötet 6 Lehrlinge des Hohen Ordens im Shen'darhochland.", tgo={{"Lehrling des Hohen Ordens"}}, star={"Götze der wandelnden Gezeiten", {"DRUID"}}},
    [94414] = {n="Die Anker von Zephras", d="Sprecht mit Halaan Hawk-Eye und leiht Euch seine Gabe, den Ankerpylon in der Entfernung zu sehen.", tgo={{"Halaan Hawk-Eye"}}},
    [94427] = {n="Eine Lektion in Sachen Göttlichkeit", d="Sprecht mit Tanis Alderwood in Undercity."},
    [94434] = {n="Eine Lektion in Sachen Göttlichkeit", d="Bringt 10 Stück Leinenstoff zu Tanis Alderwood in Undercity."},
    [94435] = {n="Eine Lektion in Sachen Göttlichkeit", d="Kehrt zu Danitha Morr in der Bandarionfestung zurück."},
    [94436] = {n="Eine Lektion in Sachen Göttlichkeit", d="Sprecht mit Todeswache Billmuth bei der Bandarionfestung.\nFalls Ihr Euer Symbol des Lebens verliert, kehrt zu Danitha Morr zurück und bittet sie um ein neues."},
    [94438] = {n="Eine Lektion in Sachen Göttlichkeit", d="Nehmt das Symbol des Lebens und benutzt es, um Todeswache Falgan im Giftwebertal wiederzubeleben.\nFalls Ihr Euer Symbol des Lebens verliert, kehrt zu Danitha Morr zurück und bittet sie um ein neues."},
    [94440] = {n="Eine Lektion in Sachen Göttlichkeit", d="Holt die Angriffspläne des Scharlachroten Kreuzzugs von den Scharlachroten Kreuzzüglern im Giftwebertal und kehrt zu Todeswache Billmuth in der Bandarionfestung zurück.", tgo={{"Scharlachroter Zelot", "Scharlachrotes Ordensmitglied", "Befleckter Fanatiker"}}},
    [94441] = {n="Eine Lektion in Sachen Göttlichkeit", d="Sprecht mit Danitha Morr in der Bandarionfestung."},
