    [98093] = {n="Das Feld säubern", d="Sulhasa im südlichen Brachland möchte, dass Ihr 7 Sturmechsen und 7 Fleischreißerpirscher in der Gegend beseitigt, damit sie sicher von dem Baum herunterkommen kann.", tgo={{"Fleischreißerpirscher"}, {"Sturmechse"}}},
    [98094] = {n="Späherunterstützung", d="Hochexekutorin Darthalia möchte, dass Ihr Todespirscher Masoj südlich von Tarrens Mühle außerhalb von Dun Garok aktualisierte Befehle überbringt."},
    [98095] = {n="Nützliche Vorteile", d="Todespirscher Masoj möchte, dass Ihr drei Phiolen des Apothekariums auf Gipfeln rund um das Vorgebirge von Hillsbrad platziert und dann zu ihm zurückkehrt."},
    [98284] = {n="Grundlagen des Zeltens: Verzauberkunst", d="Geht nach Shen'dar und sprecht mit Nasalanna Windsinger, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", tgo={{"Nasalanna Windsinger"}}},
    [98298] = {n="Arugals Torheit", d="Bringt 6 Worgenstückchen zu Dalar Dawnweaver am Grabmal.", tgo={{"Moonrage-Blutheuler"}}},
    [98299] = {n="Die Ausbreitung eindämmen", d="Tötet 5 kränkliche Flüchtlinge und 5 hagere Flüchtlinge für Dalar Dawnweaver am Grabmal.", tgo={{"Hagerer Flüchtling"}, {"Kränklicher Flüchtling"}}},
    [98340] = {n="Der große Katzengeist", d="Sprecht mit Dendrite Starblaze in Nighthaven in Moonglade."},
    [98341] = {n="Der Große windgetragene Katzengeist", d="Sucht den Avatar von Saeyleenan im südlichen Teil von Moonglade auf und lernt alles, was er Euch über die Natur der windgetragenen Katze mitzuteilen hat."},
    [98342] = {n="Der große Katzengeist", d="Beschafft das Relikt des Reißzahns, das Relikt der Klaue und das Relikt des stillen Schattens aus dem Grabhügel des Stormrage und bringt die Relikte zum großen Katzengeist zurück.", objs={"Relikt des Fangzahns", "Relikt der Klaue", "Relikt des stillen Schattens"}},
    [98362] = {n="Nach Thunder Bluff", d="Kehrt nach Thunder Bluff zurück und sprecht mit Turak Runetotem auf der Anhöhe der Ältesten."},
    [98389] = {n="Ein Licht in der Dunkelheit", d="Befreit 6 eingesponnene Opfer im Nachtwebergrund für Aramis Hammerhand in Deathknell."},
    [98404] = {n="Der Große windgetragene Katzengeist", d="Beschafft das Relikt des Reißzahns, das Relikt der Klaue und das Relikt des stillen Schattens aus dem Grabhügel des Stormrage und bringt die Relikte zum Avatar von Saeyleenan zurück.", objs={"Relikt des Fangzahns", "Relikt der Klaue", "Relikt des stillen Schattens"}},
    [98405] = {n="Der große Katzengeist", d="Sucht den großen Katzengeist im südlichen Teil von Moonglade auf und lernt alles, was er Euch über die Natur der Katze mitzuteilen hat."},
    [98424] = {n="Fizsprockets Notizen", d="Sammelt die übrigen Seiten von Vorsteher Fizsprockets Notizbuch in der Mine der Venture Co. und bringt sie zu Morin Cloudstalker am Dorf der Bloodhoof.", objs={"Schredderbedienungsanleitung", "Bewährte Praktiken für Operationen im Brachland", "Ein gewisser Gerenzo aus dem Steinkrallengebirge"}},
    [98427] = {n="Schluss damit!", d="Bringt den Mechanoroderschlüssel zu Morin Cloudstalker am Dorf der Bloodhoof.", tgo={{"Roder der Venture Co."}}},
    [98430] = {n="Die Langläufer", d="Helft Perith Stormhoof bei der Flucht aus dem Bleichmähnenfels und meldet Cairne Bloodhoof in Thunder Bluff, dass er in Sicherheit ist."},
    [98435] = {n="Thunderhorns Bericht", d="Bringt Thunderhorns Bericht zu Erzdruide Hamuul Runentotem in Thunder Bluff."},
    [98512] = {n="Auftragsmörder der Al'Aketh", d="Tötet 10 Auftragsmörder der Al'Aketh im Shen'darhochland.", tgo={{"Auftragsmörder der Al'Aketh"}}},
    [98575] = {n="Besudelte Tafel", d="Lest die besudelte Tafel und sprecht mit Nartok im Höhlenbau im Tal der Prüfungen."},
    [98576] = {n="Glyphenpergament", d="Lest das Glyphenpergament und sprecht mit Mai'ah beim Eingang zum Höhlenbau im Tal der Prüfungen."},
    [98601] = {n="Ein schwieriger Pfad", d="Lest die geweihte Schriftrolle und sprecht mit Aramis Hammerhand in der Kirche von Deathknell."},
    [98738] = {n="Segen des großen windgetragenen Katzengeistes", d="Sucht den großen Bärengeist im nordwestlichen Moonglade auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Starblaze nach Nighthaven in Moonglade zurück."},
    [98739] = {n="Segen des großen Katzengeistes", d="Sprecht mit Dendrite."},
    [98823] = {n="Irdenes Echo", d="Bringt das Relikt der Titanen zu Muln Earthfury beim Himmelsschauerplateau im Nordwesten von Mulgore."},
    [99048] = {n="Hand vermisst", d="Findet Heglan Shadeeye nördlich von Burg Tiragarde."},
    [99049] = {n="Bedrohung von unten", d="Findet Hinweise darauf, was Heglan Shadeeye angegriffen hat.", objs={"Zurückgelassener Dolch", "Seltsame Trümmer", "Waffenteile"}},
    [99051] = {n="Bedrohung von unten", d="Sammelt 9 Nagastachelflossen ein.", tgo={{"Späher der Grollflossen", "Bedienstete der Grollflossen"}}},
    [99052] = {n="Bedrohung von unten", d="Tötet den Meeresriesen an der Nordküste von Durotar und bringt einen Beweis für Euren Erfolg zurück.", tgo={{"Aggor der Junge"}}},
    [99079] = {n="Langläuferin Malah", d="Findet Langläuferin Malah Longwind östlich des Dorfes der Bloodhoof, nahe Mulgore."},
    [99080] = {n="Vertreibt sie", d="Tötet 6 Zentauren der Galak und 4 Kundschafter der Galak und bringt den Kopf von Herak dem Plünderer zu Baine Bloodhoof.", tgo={{"Zentaur der Galak"}, {"Kundschafter der Galak"}, {"Herak der Plünderer"}}},
    [99081] = {n="Schwieriges Unterfangen", d="Bringt den Bericht von Langläuferin Malah zu Kriegerheld Wildrunner im Dorf der Bloodhoof."},
    [99082] = {n="Der Oberhäuptling", d="Ersucht in Thunder Bluff um eine Audienz beim Oberhäuptling Cairne Bloodhoof."},
    [99101] = {n="Unser uralter Feind", d="Bringt den Bericht von Langläuferin Malah zu Baine Bloodhoof."},
    [99108] = {n="Sparringskampf", d="Besiegt 3 andere Spielercharaktere in Duellen oder Novizenkrieger für Tang Stonehoof.", tgo={{"Kriegernovize"}}},
    [99123] = {n="Verloren in den Schatten", d="Helft Pal'juh, aus der Kolkarklippe zu entkommen, und berichtet anschließend Meister Vornal in Sen'jin davon."},
    [99134] = {n="Disziplin", d="Bestraft 5 Todeswachen für Exekutor Zygand."},
    [99141] = {n="Geduld", d="Besorgt die Berichte von Todeswache Dillinger, Todeswache Kristof und Gordo für Exekutor Zygand.", tgo={{"Todeswache Dillinger"}, {"Todeswache Kristof"}, {"Gordo"}}},
    [99142] = {n="Grabkraut", d="Sammelt 5 Grabkräuter und bringt sie zu Jungapotheker Holland.", objs={"Grabkraut"}},
    [99156] = {n="Patrouille zur Rückendeckung", d="Bringt Reißers Herz zu Todeswache Linnea.", tgo={{"Reißer"}}},
    [99187] = {n="Das Reliquiar von Tyr", d="Reist zur Schwarzschlundfeste in Kalimdor und bergt das Reliquiar von Tyr.", star={"Sword of Mourning", {"PALADIN"}}},
    [99411] = {n="Kyle wird vermisst!", d="Ahab Weizhuf in Bloodhoof in Mulgore möchte, dass Ihr seinen geliebten Hund Kyle den Wilden füttert.\nFüttert Kyle mit zartem Schreiterfleisch und kehrt anschließend zu Ahab Weizhuf zurück.", tgo={{"Kyle der Wilde"}}},
  },
